def _historical_accepted_requested_row_ids_for_support(
    operator_root: str | Path,
    *,
    support_request_id: str,
    target_artifact: str,
    current_requested_row_ids: Iterable[str],
    limit: int = 250,
) -> list[str]:
    support_id = str(support_request_id or "").strip()
    requested_set = {
        str(item or "").strip()
        for item in list(current_requested_row_ids or [])
        if str(item or "").strip()
    }
    if not support_id or not requested_set:
        return []
    rows: list[dict[str, Any]] = []
    rows.extend(_read_ledger(operator_root, "directive_build_grade_support_digests", limit=limit))
    rows.extend(_support_field_lane_acquisition_rows(operator_root, limit=limit))
    latest_digest = _read_json(
        autonomy_root(operator_root) / "directive_build_grade_support_digest_latest.json"
    )
    if latest_digest:
        rows.append(latest_digest)
    accepted: list[str] = []
    for row in rows:
        row_support_id = str(
            row.get("support_request_id", "")
            or row.get("current_provider_support_request_id", "")
            or ""
        ).strip()
        if row_support_id != support_id:
            continue
        row_target = str(row.get("target_artifact", "") or "").strip()
        if target_artifact and row_target and row_target != target_artifact:
            continue
        for requested_id in list(row.get("accepted_requested_row_ids", []) or []):
            requested_id = str(requested_id or "").strip()
            if requested_id and requested_id in requested_set:
                accepted.append(requested_id)
    return list(dict.fromkeys(accepted))


def _close_decomposed_abstract_requested_rows(
    *,
    accepted_requested_row_ids: Iterable[str],
    uncovered_requested_row_ids: Iterable[str],
    decomposed_abstract_requested_rows: Iterable[Mapping[str, Any]],
) -> tuple[list[str], list[str], list[str]]:
    accepted = [
        str(item or "").strip()
        for item in list(accepted_requested_row_ids or [])
        if str(item or "").strip()
    ]
    accepted_set = set(accepted)
    uncovered = [
        str(item or "").strip()
        for item in list(uncovered_requested_row_ids or [])
        if str(item or "").strip()
    ]
    closed: list[str] = []
    for row in list(decomposed_abstract_requested_rows or []):
        if not isinstance(row, Mapping):
            continue
        parent_id = str(row.get("requested_row_id", "") or "").strip()
        child_ids = [
            str(item or "").strip()
            for item in list(row.get("decomposed_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        if parent_id and parent_id in uncovered and child_ids and set(child_ids).issubset(accepted_set):
            accepted.append(parent_id)
            accepted_set.add(parent_id)
            closed.append(parent_id)
    if not closed:
        return list(dict.fromkeys(accepted)), list(dict.fromkeys(uncovered)), []
    return (
        list(dict.fromkeys(accepted)),
        [item for item in list(dict.fromkeys(uncovered)) if item not in set(closed)],
        list(dict.fromkeys(closed)),
    )


def _historical_engineering_evidence_rows_for_requested_ids(
    operator_root: str | Path,
    *,
    support_request_id: str,
    target_artifact: str,
    requested_row_ids: Iterable[str],
    limit: int = 1000,
) -> list[dict[str, Any]]:
    support_id = str(support_request_id or "").strip()
    requested_set = {
        str(item or "").strip()
        for item in list(requested_row_ids or [])
        if str(item or "").strip()
    }
    if not support_id or not requested_set:
        return []
    rows_by_requested_id: dict[str, dict[str, Any]] = {}
    for row in _read_conveyor_ledger(operator_root, "engineering_evidence_rows", limit=limit):
        row_support_id = str(row.get("support_request_id", "") or "").strip()
        requested_id = str(row.get("requested_row_id", "") or "").strip()
        row_target = str(row.get("target_artifact", "") or "").strip()
        if row_support_id != support_id or requested_id not in requested_set:
            continue
        if target_artifact and row_target and row_target != target_artifact:
            continue
        if bool(row.get("grants_execution_authority", False)):
            continue
        if not str(row.get("evidence_ref", "") or "").strip():
            continue
        if not (
            _build_grade_source_is_concrete(str(row.get("source_url", "") or ""))
            or _build_grade_source_is_concrete(str(row.get("citation_ref", "") or ""))
            or str(row.get("source_hint", "") or "").strip()
        ):
            continue
        normalized = dict(row)
        normalized["grants_execution_authority"] = False
        rows_by_requested_id[requested_id] = normalized
    return [rows_by_requested_id[item] for item in requested_set if item in rows_by_requested_id]


