def _risk_control_materialization_closure_rows(
    operator_root: str | Path,
    *,
    limit: int = 100,
) -> list[dict[str, Any]]:
    progress_root = Path(operator_root) / "conveyor" / "progress"
    rows: list[dict[str, Any]] = []
    # Normal operation consumes a kernel-produced receipt. Directory scans are
    # only an explicit legacy-recovery path, never part of default status reads.
    receipt_path = progress_root.parent / "risk_control_materialization_evidence_latest.json"
    receipt = _read_json(receipt_path) if receipt_path.is_file() else {}
    if (
        receipt.get("target_artifact") == "risk_controls.json"
        and receipt.get("closed_target_artifact") == "risk_controls.json"
        and receipt.get("next_linked_artifact_target") == "validation_fixtures.json"
        and receipt.get("kernel_consumed_gate_closure") is True
        and receipt.get("target_correct_gate_closure") is True
        and receipt.get("partial_target_correct_closure") is True
        and receipt.get("closed_failed_gates")
        and not receipt.get("unchanged_failed_gates")
        and receipt.get("directive_id") and receipt.get("quality_growth_evidence_id")
        and receipt.get("grants_execution_authority") is False
    ):
        rows.append(receipt)
    if progress_root.exists():
        try:
            configured_scan_limit = int(
                os.environ.get("NOVALI_AUTONOMY_PROGRESS_PROOF_SCAN_LIMIT", "0")
            )
        except (TypeError, ValueError):
            configured_scan_limit = 0
        scan_limit = max(0, min(512, configured_scan_limit))
        if scan_limit <= 0:
            return rows
        try:
            max_age_seconds = float(
                os.environ.get(
                    "NOVALI_AUTONOMY_PROGRESS_PROOF_SCAN_MAX_AGE_SECONDS",
                    "604800",
                )
            )
        except (TypeError, ValueError):
            max_age_seconds = 604800.0
        try:
            max_bytes = int(
                os.environ.get("NOVALI_AUTONOMY_PROGRESS_PROOF_MAX_BYTES", "262144")
            )
        except (TypeError, ValueError):
            max_bytes = 262144
        now_ts = time.time()
        progress_paths: list[Path] = []
        try:
            for child_progress_root in progress_root.iterdir():
                if len(progress_paths) >= scan_limit:
                    break
                if not child_progress_root.is_dir():
                    continue
                progress_path = child_progress_root / "progress_latest.json"
                if progress_path.is_file():
                    try:
                        stat = progress_path.stat()
                    except OSError:
                        continue
                    if max_age_seconds > 0 and now_ts - stat.st_mtime > max_age_seconds:
                        continue
                    if max_bytes > 0 and stat.st_size > max_bytes:
                        continue
                    progress_paths.append(progress_path)
        except OSError:
            progress_paths = []
        for path in progress_paths:
            progress = _read_json(path)
            if str(progress.get("target_artifact", "") or "") != "risk_controls.json":
                continue
            if str(progress.get("risk_control_materialization_state", "") or "") != "materialized":
                continue
            if list(progress.get("missing_fmea_row_refs", []) or []):
                continue
            try:
                materialized_count = int(progress.get("risk_control_materialized_count", 0) or 0)
            except (TypeError, ValueError):
                materialized_count = 0
            materialized_rows = [
                str(item)
                for item in list(progress.get("risk_control_materialized_rows", []) or [])
                if str(item).strip()
            ]
            if materialized_count <= 0 and not materialized_rows:
                continue
            created_at = str(progress.get("generated_at", "") or progress.get("created_at", "") or "")
            evidence = {
                "schema_name": "RiskControlMaterializationEvidence",
                "schema_version": AUTONOMY_SCHEMA_VERSION,
                "created_at": created_at,
                "generated_at": created_at,
                "directive_id": str(progress.get("directive_id", "") or ""),
                "child_run_id": str(progress.get("child_run_id", "") or path.parent.name),
                "target_artifact": "risk_controls.json",
                "closed_target_artifact": "risk_controls.json",
                "next_linked_artifact_target": "validation_fixtures.json",
                "partial_target_correct_closure": True,
                "risk_control_materialization_state": "materialized",
                "risk_control_materialized_count": materialized_count or len(materialized_rows),
                "risk_control_materialized_rows": materialized_rows,
                "missing_fmea_row_refs": [],
                "grants_execution_authority": False,
            }
            evidence["risk_control_materialization_evidence_id"] = _record_id(
                "risk-control-materialization",
                evidence,
            )
            rows.append(evidence)
    rows.sort(key=lambda row: str(row.get("created_at", "") or row.get("generated_at", "") or ""))
    return rows[-max(1, int(limit or 1)) :]


