def _strict_consumption_signal_present(row: Mapping[str, Any]) -> bool:
    return bool(
        row.get("strict_usefulness_credited", False)
        or row.get("strict_useful_capability_consumed", False)
        or row.get("decision_changed_by_capability", False)
        or row.get("repeat_failure_prevented", False)
        or row.get("budget_prevented_overrun", False)
        or float(row.get("directive_progress_delta", 0.0) or 0.0) > 0.0
    )


def _concrete_strict_consumption_effect_present(row: Mapping[str, Any]) -> bool:
    return bool(
        _strict_consumption_signal_present(row)
        and (
            str(row.get("capability_consumption_event_id", "") or "").strip()
            or list(row.get("consumed_capability_kinds", []) or [])
            or list(row.get("explicitly_consumed_capability_kinds", []) or [])
            or list(row.get("planner_hook_references", []) or [])
            or list(row.get("runtime_hook_references", []) or [])
            or row.get("repeat_failure_prevented", False)
            or row.get("budget_prevented_overrun", False)
            or float(row.get("directive_progress_delta", 0.0) or 0.0) > 0.0
        )
    )


def _handoff_intent_preservation_assessment(operator_root: str | Path) -> dict[str, Any]:
    rows = _read_ledger(operator_root, "conveyor_intent_continuity_events", limit=100)
    relevant = [
        dict(row)
        for row in rows
        if str(row.get("intended_target_artifact", "") or "").strip()
    ]
    if not relevant:
        return {
            "score": 1.0,
            "event_count": 0,
            "preserved_count": 0,
            "lost_count": 0,
            "latest_preserved": True,
            "latest_failed_gates": [],
            "latest_event": {},
        }
    preserved_count = sum(1 for row in relevant if bool(row.get("preserved", False)))
    latest = relevant[-1]
    failed_gates = [
        str(item)
        for item in list(latest.get("failed_gates", []) or [])
        if str(item).strip()
    ]
    return {
        "score": round(preserved_count / max(1, len(relevant)), 3),
        "event_count": len(relevant),
        "preserved_count": preserved_count,
        "lost_count": len(relevant) - preserved_count,
        "latest_preserved": bool(latest.get("preserved", False)),
        "latest_failed_gates": failed_gates,
        "latest_event": latest,
    }


def _corrective_gate_closure_assessment(operator_root: str | Path) -> dict[str, Any]:
    rows = [
        dict(row)
        for row in _read_ledger(operator_root, "conveyor_quality_growth_evidence", limit=100)
        if (
            list(row.get("closed_failed_gates", []) or [])
            or list(row.get("unchanged_failed_gates", []) or [])
            or list(row.get("required_gate_closures", []) or [])
            or list(row.get("failed_quality_gates", []) or [])
            or bool(row.get("gate_closure_since_last_cycle", False))
        )
    ]
    if not rows:
        return {
            "score": 1.0,
            "event_count": 0,
            "closure_event_count": 0,
            "stalled_event_count": 0,
            "latest_gate_closure": True,
            "latest_closed_failed_gates": [],
            "latest_unchanged_failed_gates": [],
            "latest_event": {},
        }
    closure_event_count = 0
    stalled_event_count = 0
    closed_total = 0
    unchanged_total = 0
    for row in rows:
        closed = [
            str(item)
            for item in list(row.get("closed_failed_gates", []) or [])
            if str(item).strip()
        ]
        unchanged = [
            str(item)
            for item in list(row.get("unchanged_failed_gates", []) or [])
            if str(item).strip()
        ]
        failed = [
            str(item)
            for item in list(row.get("failed_quality_gates", []) or [])
            if str(item).strip()
        ]
        if bool(row.get("gate_closure_since_last_cycle", False)) or closed:
            closure_event_count += 1
        elif unchanged or failed or list(row.get("required_gate_closures", []) or []):
            stalled_event_count += 1
        closed_total += len(set(closed))
        unchanged_total += len(set(unchanged or failed))
    latest = rows[-1]
    latest_closed = [
        str(item)
        for item in list(latest.get("closed_failed_gates", []) or [])
        if str(item).strip()
    ]
    latest_unchanged = [
        str(item)
        for item in list(latest.get("unchanged_failed_gates", []) or [])
        if str(item).strip()
    ]
    denominator = max(1, closed_total + unchanged_total)
    score = closed_total / denominator
    if closure_event_count and not unchanged_total:
        score = 1.0
    return {
        "score": round(max(0.0, min(1.0, score)), 3),
        "event_count": len(rows),
        "closure_event_count": closure_event_count,
        "stalled_event_count": stalled_event_count,
        "latest_gate_closure": bool(latest.get("gate_closure_since_last_cycle", False) or latest_closed),
        "latest_closed_failed_gates": latest_closed,
        "latest_unchanged_failed_gates": latest_unchanged,
        "latest_event": latest,
    }


def _target_correct_gate_closure_assessment(operator_root: str | Path) -> dict[str, Any]:
    transition_actions = {
        "retarget_next_unresolved_artifact",
        "request_final_return",
        "operator_review_ready",
        "novel_clarification_requested",
        "productive_quiescence",
    }

    def schema_followup_closure_allowed(row: Mapping[str, Any]) -> bool:
        if not bool(row.get("schema_resonance_followup_required", False)):
            return True
        missing_fields = list(
            row.get("schema_followup_missing_top_level_fields", [])
            or row.get("missing_top_level_fields", [])
            or []
        )
        try:
            schema_score = float(row.get("schema_resonance_score", 0.0) or 0.0)
        except (TypeError, ValueError):
            schema_score = 0.0
        return bool(row.get("schema_followup_contract_satisfied", False)) and not missing_fields and schema_score >= 1.0

    def prototype_proof_closure_allowed(row: Mapping[str, Any]) -> bool:
        if str(row.get("source", "") or "") != "prototype_promotion_proof_receipt":
            return True
        return bool(
            row.get("promotion_proof_eligible", False)
            and str(row.get("prototype_promotion_proof_receipt_id", "") or "").strip()
            and not bool(row.get("grants_execution_authority", False))
            and list(row.get("safety_gates_preserved", []) or [])
        )

    rows = [
        dict(row)
        for row in _read_ledger(operator_root, "conveyor_quality_growth_evidence", limit=100)
        if (
            "target_correct_gate_closure" in row
            or bool(row.get("kernel_consumed_gate_closure", False))
            or list(row.get("required_gate_closures", []) or [])
            or list(row.get("closed_failed_gates", []) or [])
            or list(row.get("unchanged_failed_gates", []) or [])
        )
    ]
    if not rows:
        return {
            "score": 1.0,
            "event_count": 0,
            "target_correct_event_count": 0,
            "off_target_event_count": 0,
            "latest_target_correct": True,
            "latest_event": {},
            "latest_next_action": "",
        }
    target_correct_count = 0
    off_target_count = 0
    for row in rows:
        closed = [
            str(item)
            for item in list(row.get("closed_failed_gates", []) or [])
            if str(item).strip()
        ]
        next_action = str(row.get("next_action_after_closure", "") or "")
        explicit = bool(row.get("target_correct_gate_closure", False))
        consumed = bool(row.get("kernel_consumed_gate_closure", False))
        target_correct = bool(
            explicit
            and consumed
            and closed
            and next_action in transition_actions
            and schema_followup_closure_allowed(row)
            and prototype_proof_closure_allowed(row)
        )
        if target_correct:
            target_correct_count += 1
        else:
            off_target_count += 1
    latest = rows[-1]
    latest_next_action = str(latest.get("next_action_after_closure", "") or "")
    latest_closed = [
        str(item)
        for item in list(latest.get("closed_failed_gates", []) or [])
        if str(item).strip()
    ]
    latest_target_correct = bool(
        latest.get("target_correct_gate_closure", False)
        and latest.get("kernel_consumed_gate_closure", False)
        and latest_closed
        and latest_next_action in transition_actions
        and schema_followup_closure_allowed(latest)
        and prototype_proof_closure_allowed(latest)
    )
    return {
        "score": round(target_correct_count / max(1, len(rows)), 3),
        "event_count": len(rows),
        "target_correct_event_count": target_correct_count,
        "off_target_event_count": off_target_count,
        "latest_target_correct": latest_target_correct,
        "latest_event": latest,
        "latest_next_action": latest_next_action,
    }


def _strict_consumption_signature(row: Mapping[str, Any]) -> str:
    capability_kinds = sorted(
        str(item)
        for item in list(row.get("consumed_capability_kinds", []) or [])
        if str(item).strip()
    )
    if not capability_kinds and str(row.get("capability_kind", "") or "").strip():
        capability_kinds = [str(row.get("capability_kind", "") or "").strip()]
    payload = {
        "capability_kinds": capability_kinds,
        "hook_reason": str(row.get("hook_reason", "") or ""),
        "target_artifact": str(row.get("target_artifact", "") or ""),
        "output_contract_signature": str(
            row.get("output_contract_signature", "")
            or row.get("work_order_signature", "")
            or row.get("input_fingerprint", "")
            or ""
        ),
        "decision_delta": str(row.get("decision_delta", "") or ""),
        "directive_progress_effect": str(row.get("directive_progress_effect", "") or ""),
        "final_action": str(row.get("final_action", "") or ""),
    }
    return _hash_payload(payload, length=16)


def _dedupe_strict_consumption_rows(rows: Iterable[Mapping[str, Any]]) -> list[dict[str, Any]]:
    deduped: list[dict[str, Any]] = []
    seen: set[str] = set()
    for row in rows:
        signature = _strict_consumption_signature(row)
        if signature in seen:
            continue
        seen.add(signature)
        payload = dict(row)
        payload["strict_consumption_signature"] = signature
        deduped.append(payload)
    return deduped


def _productive_quiescence_assessment(operator_root: str | Path) -> dict[str, Any]:
    conveyor_child_events: list[dict[str, Any]] = []
    conveyor_path = Path(operator_root) / "conveyor" / "ledgers" / "child_events.jsonl"
    if conveyor_path.exists():
        rows: deque[dict[str, Any]] = deque(maxlen=200)
        try:
            with conveyor_path.open("r", encoding="utf-8") as handle:
                for line in handle:
                    if not line.strip():
                        continue
                    rows.append(json.loads(line))
            conveyor_child_events = list(rows)
        except (OSError, json.JSONDecodeError):
            conveyor_child_events = []
    rows = [
        dict(row)
        for row in [*_read_ledger(operator_root, "child_events", limit=200), *conveyor_child_events]
        if str(row.get("event", "") or "") == "resident_followup_delta_satisfied_return_requested"
        and bool(row.get("productive_quiescence_eligible", False))
    ]
    return {
        "score": 1.0 if rows else 0.0,
        "event_count": len(rows),
        "latest_event": rows[-1] if rows else {},
    }


def _schema_resonance_runtime_assessment(operator_root: str | Path) -> dict[str, Any]:
    rows = [
        dict(row)
        for row in _read_ledger(operator_root, "promotion_mismatch_events", limit=100)
        if isinstance(row.get("schema_resonance", {}), Mapping)
    ]
    if not rows:
        return {
            "score": 1.0,
            "event_count": 0,
            "gap_event_count": 0,
            "latest_state": "not_observed",
            "latest_event": {},
        }
    scores = [
        max(0.0, min(1.0, float(dict(row.get("schema_resonance", {}) or {}).get("score", 0.0) or 0.0)))
        for row in rows
    ]
    latest = rows[-1]
    latest_resonance = dict(latest.get("schema_resonance", {}) or {})
    gap_count = sum(1 for score in scores if score < 1.0)
    return {
        "score": round(sum(scores) / max(1, len(scores)), 3),
        "event_count": len(rows),
        "gap_event_count": gap_count,
        "latest_state": str(latest_resonance.get("state", "") or latest.get("state", "")),
        "latest_missing_fields": list(latest_resonance.get("required_fields_missing", []) or []),
        "latest_event": latest,
    }


def _consumption_churn_assessment(
    consumption_rows: Iterable[Mapping[str, Any]],
    *,
    corrective_gate_closure: Mapping[str, Any],
    productive_quiescence: Mapping[str, Any],
) -> dict[str, Any]:
    strict_rows = [dict(row) for row in consumption_rows if _strict_consumption_signal_present(row)]
    signature_counts: dict[str, int] = {}
    for row in strict_rows:
        signature = _strict_consumption_signature(row)
        signature_counts[signature] = signature_counts.get(signature, 0) + 1
    duplicate_count = sum(max(0, count - 1) for count in signature_counts.values())
    closure_count = int(corrective_gate_closure.get("closure_event_count", 0) or 0)
    quiescence_count = int(productive_quiescence.get("event_count", 0) or 0)
    churn_active = bool(duplicate_count >= 3 and closure_count <= 0 and quiescence_count <= 0)
    return {
        "score": 0.25 if churn_active else 1.0,
        "state": "active" if churn_active else "clear",
        "strict_event_count": len(strict_rows),
        "unique_strict_event_count": len(signature_counts),
        "duplicate_strict_event_count": duplicate_count,
        "closure_event_count": closure_count,
        "productive_quiescence_count": quiescence_count,
        "repeated_signatures": [
            {"signature": signature, "count": count}
            for signature, count in sorted(signature_counts.items())
            if count > 1
        ][:10],
    }


def _continuation_dominance_evaluation(
    operator_root: str | Path,
    *,
    persist: bool = True,
) -> dict[str, Any]:
    charter = load_autonomy_charter(operator_root)
    policy = dict(charter.get("consumption_gap_policy", {}) or {})
    enabled = bool(policy.get("enabled", True))
    try:
        threshold = int(
            policy.get("governed_continuation_without_strict_usefulness_threshold", 7)
            or 7
        )
    except (TypeError, ValueError):
        threshold = 7
    threshold = max(1, min(50, threshold))
    preferred_actions = [
        str(item).strip()
        for item in list(policy.get("preferred_actions", []) or [])
        if str(item).strip()
    ] or ["post_ladder_synthesis", "adaptive_learning_synthesis"]
    preferred_actions = [
        action for action in preferred_actions if action in SUPPORTED_OPERATION_ACTIONS
    ] or ["post_ladder_synthesis", "adaptive_learning_synthesis"]

    operation_rows = _read_ledger(operator_root, "operation_results", limit=200)
    meaningful_rows = _read_ledger(operator_root, "meaningful_work_evaluations", limit=200)
    consumption_rows = _read_ledger(operator_root, "capability_consumption_events", limit=200)
    usefulness = _latest(operator_root, "capability_usefulness_evaluations")
    strict_usefulness_present = bool(
        usefulness.get("strict_usefulness_gate_passed", False)
        and str(usefulness.get("usefulness", "")) == "useful"
    ) or any(_strict_consumption_signal_present(row) for row in consumption_rows + meaningful_rows)

    reset_cutoffs = [
        _record_created_at(_latest(operator_root, "trusted_source_literature_triage_digests")),
        _record_created_at(_latest(operator_root, "post_ladder_syntheses")),
        _record_created_at(_latest(operator_root, "adaptive_learning_syntheses")),
    ]
    strict_effect_cutoffs = [
        _record_created_at(row)
        for row in consumption_rows + meaningful_rows
        if _concrete_strict_consumption_effect_present(row)
    ]
    latest_strict_effect_at = max(
        [item for item in strict_effect_cutoffs if item is not None],
        default=None,
    )
    reset_cutoff = max([item for item in reset_cutoffs if item is not None], default=None)
    governed_count = 0
    governed_window_start = None
    for row in reversed(operation_rows):
        if reset_cutoff is not None and not _after_created_at(row, reset_cutoff):
            break
        if latest_strict_effect_at is not None and not _after_created_at(
            row, latest_strict_effect_at
        ):
            break
        if _strict_consumption_signal_present(row):
            break
        if str(row.get("action", "")) == "governed_start_next_invocation":
            governed_count += 1
            created_at = _record_created_at(row)
            if created_at is not None:
                governed_window_start = created_at
            continue
        if str(row.get("action", "")) in {
            "post_ladder_synthesis",
            "adaptive_learning_synthesis",
            "trusted_source_literature_triage_digest",
        }:
            break
    recent_strict_usefulness_present = strict_usefulness_present
    if governed_window_start is not None:
        recent_strict_usefulness_present = any(
            _strict_consumption_signal_present(row)
            and _after_created_at(row, governed_window_start)
            for row in consumption_rows + meaningful_rows
        )

    promoted_rows = [
        row
        for row in _read_ledger(operator_root, "promotion_results", limit=100)
        if str(row.get("status", "")) == "promoted"
        or str(row.get("promotion_stage", "")) == "promoted"
    ]
    needs_usefulness_classification = bool(promoted_rows and not strict_usefulness_present)
    recommended_action = ""
    reason = "continuation cadence is below the consumption gap threshold"
    state = "clear"
    if not enabled:
        state = "disabled"
        reason = "consumption gap policy is disabled"
    elif governed_count >= threshold and not recent_strict_usefulness_present:
        state = "active"
        if needs_usefulness_classification and "post_ladder_synthesis" in preferred_actions:
            recommended_action = "post_ladder_synthesis"
        elif "adaptive_learning_synthesis" in preferred_actions:
            recommended_action = "adaptive_learning_synthesis"
        else:
            recommended_action = preferred_actions[0]
        reason = (
            f"{governed_count} governed continuations ran without strict usefulness; "
            f"select {recommended_action} before another governed continuation"
        )

    evaluation = {
        "schema_name": CONTINUATION_DOMINANCE_EVALUATION_SCHEMA_NAME,
        "schema_version": AUTONOMY_SCHEMA_VERSION,
        "created_at": _now(),
        "continuation_dominance_id": "",
        "continuation_dominance_state": state,
        "enabled": enabled,
        "governed_continuations_without_strict_usefulness": governed_count,
        "threshold": threshold,
        "strict_usefulness_present": strict_usefulness_present,
        "recent_strict_usefulness_present": recent_strict_usefulness_present,
        "needs_usefulness_classification": needs_usefulness_classification,
        "preferred_actions": preferred_actions,
        "recommended_action": recommended_action,
        "reason": reason,
    }
    evaluation["continuation_dominance_id"] = _record_id("continuation-dominance", evaluation)
    if persist:
        record = _append_diagnostic_transition(operator_root, "continuation_dominance_evaluations", evaluation)
        _write_json(
            autonomy_root(operator_root) / "continuation_dominance_evaluation_latest.json",
            record,
        )
        return record
    return evaluation


def _nine_d_band(score: float, *, threshold_met: bool) -> str:
    if threshold_met:
        return "criticality_candidate"
    if score >= 0.75:
        return "threshold_adjacent"
    if score >= 0.60:
        return "self_structuring"
    if score >= 0.35:
        return "scaffolded"
    return "seed"


def _nine_d_capability_maturity_scorecard(
    operator_root: str | Path,
    *,
    persist: bool = True,
) -> dict[str, Any]:
    meaningful_rows = _read_ledger(operator_root, "meaningful_work_evaluations", limit=200)
    operation_rows = _read_ledger(operator_root, "operation_results", limit=200)
    promotion_rows = _read_ledger(operator_root, "promotion_results", limit=100)
    consumption_rows = _read_ledger(operator_root, "capability_consumption_events", limit=200)
    usefulness = _latest(operator_root, "capability_usefulness_evaluations")
    rollback_rows = _read_ledger(operator_root, "rollback_records", limit=200)
    dominance = _continuation_dominance_evaluation(operator_root, persist=False)
    handoff_intent = _handoff_intent_preservation_assessment(operator_root)
    corrective_gate_closure = _corrective_gate_closure_assessment(operator_root)
    target_correct_gate_closure = _target_correct_gate_closure_assessment(operator_root)
    productive_quiescence = _productive_quiescence_assessment(operator_root)
    schema_resonance = _schema_resonance_runtime_assessment(operator_root)
    consumption_churn = _consumption_churn_assessment(
        consumption_rows,
        corrective_gate_closure=corrective_gate_closure,
        productive_quiescence=productive_quiescence,
    )
    proof_rows = _read_ledger(operator_root, "capability_consumption_proofs", limit=200)
    latest_proof = _latest(operator_root, "capability_consumption_proofs")
    if not latest_proof:
        latest_proof = _capability_consumption_proof(operator_root, persist=False)
    evidence_present = bool(
        meaningful_rows or operation_rows or promotion_rows or consumption_rows or usefulness or proof_rows
    )

    meaningful_density = 0.0
    if meaningful_rows:
        meaningful_density = sum(
            float(row.get("total_score", 1.0 if row.get("meaningful_delta", False) else 0.0) or 0.0)
            for row in meaningful_rows
        ) / max(1, len(meaningful_rows))
    capability_kinds = {
        str(row.get("capability_kind", "") or "").strip()
        for row in meaningful_rows + promotion_rows + consumption_rows
        if str(row.get("capability_kind", "") or "").strip()
    }
    capability_diversity = min(1.0, len(capability_kinds) / 6.0)
    governed_rows = [
        row for row in operation_rows if str(row.get("action", "")) == "governed_start_next_invocation"
    ]
    governed_success = (
        sum(1 for row in governed_rows if str(row.get("status", "")) == "completed")
        / max(1, len(governed_rows))
        if governed_rows
        else 0.0
    )
    schema_resonance_score = float(schema_resonance.get("score", 1.0) or 0.0)
    productive_complexity = round(
        min(
            1.0,
            (capability_diversity * 0.20)
            + (float(target_correct_gate_closure.get("score", 1.0) or 0.0) * 0.30)
            + (float(productive_quiescence.get("score", 0.0) or 0.0) * 0.20)
            + (schema_resonance_score * 0.20)
            + (min(1.0, len(consumption_rows) / 5.0) * 0.10),
        ),
        3,
    ) if evidence_present else 0.0
    c1_complexity = (
        round(
            min(
                1.0,
                (meaningful_density * 0.45)
                + (capability_diversity * 0.20)
                + (productive_complexity * 0.25)
                + (governed_success * 0.10),
            ),
            3,
        )
        if evidence_present
        else 0.0
    )

    promoted_kinds = {
        str(row.get("capability_kind", "") or "").strip()
        for row in promotion_rows
        if str(row.get("status", "")) == "promoted"
        or str(row.get("promotion_stage", "")) == "promoted"
    }
    strict_consumption_rows_raw = [
        row
        for row in consumption_rows
        if _strict_consumption_signal_present(row)
        and bool(row.get("target_correct_gate_closure", False))
        and (
            bool(row.get("repeat_failure_prevented", False))
            or bool(row.get("budget_prevented_overrun", False))
            or float(row.get("directive_progress_delta", 0.0) or 0.0) > 0.0
            or bool(row.get("strict_usefulness_credited", False))
            or bool(row.get("strict_useful_capability_consumed", False))
        )
        and (
            not promoted_kinds
            or str(row.get("capability_kind", "") or "").strip() in promoted_kinds
            or any(
                str(item).strip() in promoted_kinds
                for item in list(row.get("consumed_capability_kinds", []) or [])
            )
        )
    ]
    strict_consumption_rows = _dedupe_strict_consumption_rows(strict_consumption_rows_raw)
    strict_meaningful_rows = [
        row for row in meaningful_rows if _strict_consumption_signal_present(row)
    ]
    strict_usefulness_latest = bool(
        usefulness.get("strict_usefulness_gate_passed", False)
        and str(usefulness.get("usefulness", "")) == "useful"
    )
    strict_proof_rows = [
        row for row in proof_rows if bool(row.get("strict_usefulness_gate_passed", False))
    ]
    strict_signal_count = (
        len(strict_proof_rows)
        + len(strict_consumption_rows)
        + len(strict_meaningful_rows)
        + (1 if strict_usefulness_latest else 0)
        + (
            1
            if bool(latest_proof.get("strict_usefulness_gate_passed", False))
            and not strict_proof_rows
            else 0
        )
    )
    strict_consumption_gate_passed = bool(strict_signal_count > 0)
    strict_signal_score = min(1.0, strict_signal_count / 3.0)
    diagnosis_signal_count = 0
    for row in meaningful_rows:
        if list(row.get("weak_areas", []) or []) or _strict_consumption_signal_present(row):
            diagnosis_signal_count += 1
    for row in operation_rows:
        if (
            str(row.get("budget_decision", "") or "")
            or str(row.get("hook_stall_status", "") or "")
            or str(row.get("trusted_source_triage_priority_status", "") or "")
        ):
            diagnosis_signal_count += 1
    if usefulness:
        diagnosis_signal_count += 1
    diagnosis_coverage = min(1.0, diagnosis_signal_count / 5.0)
    blocker_prediction = (
        sum(
            1
            for row in operation_rows
            if str(row.get("budget_decision", "") or "")
            or str(row.get("hook_stall_status", "") or "")
            or str(row.get("trusted_source_triage_priority_status", "") or "")
        )
        / max(1, len(operation_rows))
        if operation_rows
        else 0.0
    )
    handoff_intent_preservation = float(handoff_intent.get("score", 1.0) or 0.0)
    corrective_gate_closure_score = float(corrective_gate_closure.get("score", 1.0) or 0.0)
    target_correct_gate_closure_score = float(target_correct_gate_closure.get("score", 1.0) or 0.0)
    productive_quiescence_score = float(productive_quiescence.get("score", 0.0) or 0.0)
    consumption_churn_control = float(consumption_churn.get("score", 1.0) or 0.0)
    c2_self_model = (
        round(
            min(
                1.0,
                (strict_signal_score * 0.20)
                + (diagnosis_coverage * 0.18)
                + (blocker_prediction * 0.13)
                + (handoff_intent_preservation * 0.13)
                + (corrective_gate_closure_score * 0.12)
                + (target_correct_gate_closure_score * 0.14)
                + (productive_quiescence_score * 0.04)
                + (schema_resonance_score * 0.04)
                + (consumption_churn_control * 0.02),
            ),
            3,
        )
        if evidence_present
        else 0.0
    )
    if int(corrective_gate_closure.get("event_count", 0) or 0) > 0 and corrective_gate_closure_score <= 0.0:
        c2_self_model = min(c2_self_model, 0.84)
    if (
        int(target_correct_gate_closure.get("event_count", 0) or 0) > 0
        and target_correct_gate_closure_score <= 0.0
    ):
        c2_self_model = min(c2_self_model, 0.84)
    if (
        strict_consumption_gate_passed
        and int(target_correct_gate_closure.get("target_correct_event_count", 0) or 0) > 0
        and bool(target_correct_gate_closure.get("latest_target_correct", False))
    ):
        c2_self_model = max(c2_self_model, 0.67)
    if str(consumption_churn.get("state", "") or "") == "active":
        c2_self_model = min(c2_self_model, 0.84)
    if int(schema_resonance.get("event_count", 0) or 0) > 0 and schema_resonance_score < 0.34:
        c2_self_model = min(c2_self_model, 0.84)

    operation_stability = (
        sum(1 for row in operation_rows if str(row.get("status", "")) == "completed")
        / max(1, len(operation_rows))
        if operation_rows
        else 0.0
    )
    rollback_needed_actions = {
        "governed_start_next_invocation",
        "promote_self_modification_candidate",
        "memory_ledger_compaction",
        "memory_pressure_archive",
        "novali_stack_restart",
    }
    rollback_needed = sum(
        1 for row in operation_rows if str(row.get("action", "")) in rollback_needed_actions
    )
    rollback_coverage = (
        min(1.0, len(rollback_rows) / max(1, rollback_needed)) if rollback_needed else 0.0
    )
    ledger_names = ("operation_results", "meaningful_work_evaluations", "approval_board_decisions")
    ledger_consistency = (
        sum(1 for name in ledger_names if _ledger_path(operator_root, name).exists())
        / len(ledger_names)
    )
    latest_churn = _latest(operator_root, "autonomy_churn_classifications")
    churn_control = 0.0 if str(latest_churn.get("churn_state", "")) == "active" else 1.0
    c3_observer_stability = (
        round(
            min(
                1.0,
                (operation_stability * 0.40)
                + (rollback_coverage * 0.25)
                + (ledger_consistency * 0.25)
                + (churn_control * 0.10),
            ),
            3,
        )
        if evidence_present
        else 0.0
    )

    criticality_score = round(
        (c1_complexity * 0.34) + (c2_self_model * 0.33) + (c3_observer_stability * 0.33),
        3,
    )
    threshold_blockers: list[str] = []
    if not strict_consumption_gate_passed:
        threshold_blockers.append("missing_strict_consumption")
    if (
        int(handoff_intent.get("event_count", 0) or 0) > 0
        and not bool(handoff_intent.get("latest_preserved", True))
    ):
        threshold_blockers.append("handoff_intent_not_preserved")
    if (
        int(corrective_gate_closure.get("event_count", 0) or 0) > 0
        and corrective_gate_closure_score < 0.34
    ):
        threshold_blockers.append("corrective_gate_closure_below_threshold")
    if (
        int(target_correct_gate_closure.get("event_count", 0) or 0) > 0
        and target_correct_gate_closure_score < 0.34
    ):
        threshold_blockers.append("target_correct_closure_below_threshold")
    if str(consumption_churn.get("state", "") or "") == "active":
        threshold_blockers.append("consumption_churn_without_closure")
    if int(schema_resonance.get("event_count", 0) or 0) > 0 and schema_resonance_score < 0.34:
        threshold_blockers.append("schema_resonance_below_threshold")
    if c2_self_model < 0.65:
        threshold_blockers.append("c2_self_model_below_threshold")
    if criticality_score < 0.75:
        threshold_blockers.append("criticality_score_below_threshold")
    criticality_threshold_met = not threshold_blockers
    band = _nine_d_band(criticality_score, threshold_met=criticality_threshold_met)
    next_action = str(dominance.get("recommended_action", "")) or (
        "post_ladder_synthesis"
        if not strict_consumption_gate_passed and promotion_rows
        else "adaptive_learning_synthesis"
        if not strict_consumption_gate_passed
        else "continue_governed_directive"
    )

    scorecard = {
        "schema_name": NINE_D_CAPABILITY_MATURITY_SCHEMA_NAME,
        "schema_version": AUTONOMY_SCHEMA_VERSION,
        "created_at": _now(),
        "scorecard_id": "",
        "c1_complexity": c1_complexity,
        "c2_self_model": c2_self_model,
        "c3_observer_stability": c3_observer_stability,
        "criticality_score": criticality_score,
        "maturity_band": band,
        "criticality_threshold_met": criticality_threshold_met,
        "strict_consumption_gate_passed": strict_consumption_gate_passed,
        "strict_consumption_signal_count": strict_signal_count,
        "latest_capability_consumption_proof": latest_proof,
        "threshold_blockers": threshold_blockers,
        "consumption_gate_reason": (
            "strict capability consumption proof chain observed"
            if strict_consumption_gate_passed
            else str(latest_proof.get("proof_state", "") or "missing_strict_consumption")
        ),
        "continuation_dominance_state": str(
            dominance.get("continuation_dominance_state", "clear")
        ),
        "continuation_dominance": dominance,
        "next_maturity_action": next_action,
        "score_components": {
            "meaningful_work_density": round(meaningful_density, 3),
            "capability_diversity": round(capability_diversity, 3),
            "productive_complexity": round(productive_complexity, 3),
            "successful_bounded_continuations": round(governed_success, 3),
            "strict_signal_score": round(strict_signal_score, 3),
            "diagnosis_coverage": round(diagnosis_coverage, 3),
            "blocker_prediction": round(blocker_prediction, 3),
            "handoff_intent_preservation": round(handoff_intent_preservation, 3),
            "corrective_gate_closure": round(corrective_gate_closure_score, 3),
            "target_correct_gate_closure": round(target_correct_gate_closure_score, 3),
            "productive_quiescence": round(productive_quiescence_score, 3),
            "schema_resonance": round(schema_resonance_score, 3),
            "consumption_churn_control": round(consumption_churn_control, 3),
            "operation_stability": round(operation_stability, 3),
            "rollback_coverage": round(rollback_coverage, 3),
            "ledger_consistency": round(ledger_consistency, 3),
            "churn_control": round(churn_control, 3),
        },
        "handoff_intent_preservation": handoff_intent,
        "corrective_gate_closure_assessment": corrective_gate_closure,
        "target_correct_gate_closure_assessment": target_correct_gate_closure,
        "productive_quiescence_assessment": productive_quiescence,
        "schema_resonance_assessment": schema_resonance,
        "consumption_churn_assessment": consumption_churn,
    }
    scorecard["scorecard_id"] = _record_id("nine-d-scorecard", scorecard)
    if persist:
        record = _append_ledger(
            operator_root,
            "nine_d_capability_maturity_scorecards",
            scorecard,
        )
        _write_json(
            autonomy_root(operator_root) / "nine_d_capability_maturity_latest.json",
            record,
        )
        return record
    return scorecard


def _latest_nine_d_capability_maturity_scorecard(operator_root: str | Path) -> dict[str, Any]:
    latest = (
        _read_json(autonomy_root(operator_root) / "nine_d_capability_maturity_latest.json")
        or _latest(operator_root, "nine_d_capability_maturity_scorecards")
    )
    components = dict((latest or {}).get("score_components", {}) or {})
    if latest and {
        "schema_resonance",
        "productive_complexity",
    }.issubset(components):
        return latest
    computed = _nine_d_capability_maturity_scorecard(operator_root, persist=False)
    if latest:
        merged = dict(computed)
        merged.update(dict(latest))
        merged["score_components"] = {
            **dict(computed.get("score_components", {}) or {}),
            **components,
        }
        merged.setdefault("schema_name", computed.get("schema_name", ""))
        merged.setdefault("schema_version", computed.get("schema_version", ""))
        merged["scorecard_migration_state"] = "preserved_latest_with_computed_defaults"
        record = _append_ledger(
            operator_root,
            "nine_d_capability_maturity_scorecards",
            merged,
        )
        _write_json(
            autonomy_root(operator_root) / "nine_d_capability_maturity_latest.json",
            record,
        )
        return record
    return computed


