def _safe_local_coding_assist_context_paths(paths: Iterable[Any]) -> list[str]:
    safe: list[str] = []
    for item in paths:
        clean = str(item or "").strip().replace("\\", "/")
        if not clean:
            continue
        if Path(clean).is_absolute() or re.match(r"^[A-Za-z]:/", clean):
            continue
        parts = [part for part in clean.split("/") if part]
        lowered_parts = [part.lower() for part in parts]
        if any(part == ".." for part in parts):
            continue
        if any(
            part in {".git", "operator_state", "runtime_data", "runtime", "logs", "node_modules"}
            for part in lowered_parts
        ):
            continue
        if any(part == ".env" or part.startswith(".env.") for part in lowered_parts):
            continue
        lowered = "/".join(lowered_parts)
        if any(
            token in lowered
            for token in (
                "secret",
                "credential",
                "credentials",
                "token",
                "apikey",
                "api_key",
                "password",
            )
        ):
            continue
        if clean not in safe:
            safe.append(clean)
        if len(safe) >= 8:
            break
    return safe


def _local_coding_assist_for_self_remediation(
    operator_root: str | Path,
    selected_remediation: Mapping[str, Any],
    existing: Mapping[str, Any],
) -> dict[str, Any]:
    payload = dict(existing or {})
    issue_class = str(selected_remediation.get("issue_class", "") or "").strip()
    if issue_class != "cheap_source_candidate_extractor_capability_required":
        return payload
    default_paths = [
        "operator_shell/autonomy.py",
        "operator_shell/conveyor.py",
        "operator_shell/support_evidence.py",
        "operator_shell/llm_interface.py",
        "operator_shell/bounded_workspace_work.py",
        "tests/test_autonomy_kernel.py",
        "tests/test_conveyor_kernel.py",
    ]
    payload["requested"] = True
    payload["context_paths"] = _safe_local_coding_assist_context_paths(
        list(payload.get("context_paths", []) or []) + default_paths
    )
    if not str(payload.get("objective", "") or "").strip():
        payload["objective"] = (
            "Design a bounded local candidate-extraction adapter for current cheap source "
            "candidates so source-backed support rows can be validated without another "
            "no-delta support tick or OpenAI escalation."
        )
    source_plan_latest = _read_json(
        autonomy_root(operator_root) / "directive_support_source_plan_latest.json"
    )
    support_digest_latest = _read_json(
        autonomy_root(operator_root) / "directive_build_grade_support_digest_latest.json"
    )
    payload["context_bundle"] = {
        "self_remediation_issue_class": issue_class,
        "recommended_action": str(selected_remediation.get("recommended_action", "") or ""),
        "support_request_id": str(selected_remediation.get("support_request_id", "") or ""),
        "target_artifact": str(selected_remediation.get("target_artifact", "") or ""),
        "observed_state": dict(selected_remediation.get("observed_state", {}) or {}),
        "expected_state": dict(selected_remediation.get("expected_state", {}) or {}),
        "source_plan_summary": {
            "support_request_id": str(source_plan_latest.get("support_request_id", "") or ""),
            "source_plan_state": str(source_plan_latest.get("source_plan_state", "") or ""),
            "source_candidate_count": int(source_plan_latest.get("source_candidate_count", 0) or 0),
            "trusted_source_rejection_reason": str(
                source_plan_latest.get("trusted_source_rejection_reason", "") or ""
            ),
        },
        "support_digest_summary": {
            "support_request_id": str(support_digest_latest.get("support_request_id", "") or ""),
            "accepted_requested_row_ids": list(
                support_digest_latest.get("accepted_requested_row_ids", []) or []
            ),
            "uncovered_requested_row_ids": list(
                support_digest_latest.get("uncovered_requested_row_ids", []) or []
            ),
            "provider_blocker": str(support_digest_latest.get("provider_blocker", "") or ""),
        },
        "grants_execution_authority": False,
    }
    return payload


def _local_qwen_coding_assist_pressure(observations: Mapping[str, Any]) -> dict[str, Any]:
    payload = dict(observations or {})
    llm_status = dict(payload.get("llm_status", {}) or {})
    request = dict(payload.get("local_coding_assist_qwen", {}) or {})
    conveyor = dict(payload.get("conveyor", {}) or {})
    promotion_mismatch = dict(
        conveyor.get("promotion_mismatch", {})
        or payload.get("promotion_mismatch", {})
        or {}
    )
    model = str(llm_status.get("model", "") or "").strip().lower()
    model_family = str(llm_status.get("model_family", "") or "").strip().lower()
    qwen_ready = (
        bool(llm_status.get("chat_available", False))
        and (model_family == "qwen3.6" or model.startswith("qwen3.6"))
    )
    current_directive = dict(payload.get("current_directive", {}) or {})
    text_probe = " ".join(
        str(value or "")
        for value in (
            request.get("objective", ""),
            payload.get("current_blocker", ""),
            payload.get("implementation_blocker", ""),
            current_directive.get("directive_summary", ""),
            current_directive.get("latest_blocker", ""),
            promotion_mismatch.get("state", ""),
            promotion_mismatch.get("reason", ""),
            promotion_mismatch.get("target_artifact", ""),
        )
    ).lower()
    mismatch_state = str(promotion_mismatch.get("state", "") or "").strip()
    mismatch_pressure = mismatch_state in {
        "draft_ready_canonical_blocked",
        "schema_resonance_gap",
        "promotion_policy_blocked",
        "draft_plateau",
    }
    coding_pressure = bool(request.get("requested", False)) or mismatch_pressure or any(
        token in text_probe
        for token in (
            "code",
            "coding",
            "test",
            "tests",
            "pytest",
            "build",
            "prototype",
            "implementation",
            "failing",
            "blocker",
        )
    )
    context_paths = _safe_local_coding_assist_context_paths(
        list(request.get("context_paths", []) or [])
    )
    if mismatch_pressure:
        context_paths = _safe_local_coding_assist_context_paths(
            context_paths
            + [
                "operator_shell/conveyor.py",
                "operator_shell/autonomy.py",
                "tests/test_operator_web_conveyor.py",
                "tests/test_autonomy_kernel.py",
            ]
        )
    objective = str(request.get("objective", "") or "").strip()
    if not objective and mismatch_pressure:
        objective = (
            "Review conveyor evaluator/promotion mismatch and produce review-only patch "
            "suggestions, tests, risk notes, and candidate implementation steps."
        )
    if not objective and coding_pressure:
        objective = "Review local coding blocker and produce review-only implementation evidence."
    return {
        "qwen_ready": qwen_ready,
        "coding_pressure": coding_pressure,
        "requested": bool(request.get("requested", False)),
        "promotion_mismatch_pressure": mismatch_pressure,
        "promotion_mismatch": promotion_mismatch,
        "objective": objective,
        "context_paths": context_paths,
        "context_bundle": dict(request.get("context_bundle", {}) or {}),
        "model": str(llm_status.get("model", "") or ""),
        "model_family": "qwen3.6"
        if model_family == "qwen3.6" or model.startswith("qwen3.6")
        else model_family,
    }


def _evidence_to_capability_candidate_pressure(operator_root: str | Path) -> dict[str, Any]:
    accepted = _accepted_capability_evidence_rows(operator_root)
    if not accepted:
        return {"candidate_due": False, "reason": "no accepted evidence"}
    latest = accepted[-1]
    payload = dict(latest.get("payload", {}) or {})
    source_kind = str(latest.get("source_kind", ""))
    source_ref = _evidence_source_ref(payload, source_kind=source_kind)
    suggestions = [
        str(value).strip()
        for value in list(
            payload.get("action_suggestions", [])
            or payload.get("implementation_steps", [])
            or payload.get("patch_suggestions", [])
            or []
        )
        if str(value).strip()
    ]
    bounded_intent = str(payload.get("bounded_change_intent", "") or "").strip()
    if not bounded_intent:
        bounded_intent = suggestions[0] if suggestions else "Convert accepted evidence into one bounded review-gated runtime improvement candidate."
    capability_kind = str(
        payload.get("capability_kind", "")
        or payload.get("candidate_capability_kind", "")
        or "evidence_compiled_growth_candidate"
    )
    signature = _evidence_to_capability_signature(
        {
            "source_ref": source_ref,
            "capability_kind": capability_kind,
            "bounded_change_intent": bounded_intent,
            "suggestions": suggestions[:5],
        }
    )
    source_evidence_id = str(source_ref.get("evidence_id", "") or "").strip()
    source_schema = str(source_ref.get("schema_name", "") or "").strip()

    def _candidate_matches_source(row: Mapping[str, Any]) -> bool:
        row_signature = str(row.get("evidence_signature", "") or "").strip()
        if row_signature and row_signature != "[REDACTED]" and row_signature == signature:
            return True
        refs = list(row.get("source_evidence_refs", []) or [])
        single_ref = row.get("source_evidence_ref", {})
        if isinstance(single_ref, Mapping):
            refs.append(dict(single_ref))
        for ref_value in refs:
            if not isinstance(ref_value, Mapping):
                continue
            if source_evidence_id and str(ref_value.get("evidence_id", "") or "").strip() != source_evidence_id:
                continue
            if source_schema and str(ref_value.get("schema_name", "") or "").strip() != source_schema:
                continue
            if source_kind and str(ref_value.get("source_kind", "") or "").strip() != source_kind:
                continue
            return True
        return False

    existing = any(
        _candidate_matches_source(row)
        for row in _read_ledger(operator_root, "evidence_to_capability_candidates", limit=100)
    )
    return {
        "candidate_due": not existing,
        "reason": "accepted evidence has no review-gated capability candidate"
        if not existing
        else "accepted evidence already compiled",
        "source_kind": source_kind,
        "source_evidence_ref": source_ref,
        "evidence_signature": signature,
        "candidate_capability_kind": capability_kind,
    }


