def _artifact_row_identity(row: Mapping[str, Any], *, fallback_prefix: str, index: int) -> str:
    for key in (
        "requested_row_id",
        "item_id",
        "row_id",
        "component_id",
        "interface_id",
        "fixture_id",
        "hazard_id",
        "step_id",
        "id",
        "name",
    ):
        value = str(row.get(key, "") or "").strip()
        if value:
            return _truncate(value, 120)
    return f"{fallback_prefix}_{index + 1}"


def _context_design_artifact_rows(context: Mapping[str, Any]) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for source in (
        context.get("design_artifact_rows"),
        context.get("artifact_rows"),
        context.get("current_draft_rows"),
    ):
        if isinstance(source, list):
            rows.extend(dict(item) for item in source if isinstance(item, Mapping))
    for snippet in list(context.get("artifact_snippets", []) or []):
        if not isinstance(snippet, Mapping):
            continue
        text = str(snippet.get("snippet", "") or "").strip()
        if not text:
            continue
        try:
            payload = json.loads(text)
        except json.JSONDecodeError:
            continue
        candidate_rows: list[Any] = []
        if isinstance(payload, Mapping):
            for key in (
                "items",
                "rows",
                "components",
                "controls",
                "fixtures",
                "validation_fixtures",
                "artifact_rows",
            ):
                value = payload.get(key)
                if isinstance(value, list):
                    candidate_rows.extend(value)
        elif isinstance(payload, list):
            candidate_rows.extend(payload)
        rows.extend(dict(item) for item in candidate_rows if isinstance(item, Mapping))
    seen: set[str] = set()
    selected: list[dict[str, Any]] = []
    for index, row in enumerate(rows[:16]):
        row_id = _artifact_row_identity(row, fallback_prefix="design_row", index=index)
        design_like = bool(row.get("technology_design_obligation_id")) or bool(
            row.get("commercial_component_source_required")
        )
        if (
            not design_like
            and not row.get("source_search_needs")
            and not row.get("proposed_subsystem_requirement")
            and not any(row.get(field) for field in ("fixture_id", "control_id", "hazard_id"))
        ):
            continue
        if row_id in seen:
            continue
        seen.add(row_id)
        material = dict(row)
        material["target_row_id"] = row_id
        selected.append(material)
    return selected[:12]


_ABSTRACT_SUPPORT_LANE_TERMS = (
    "fixture",
    "harness",
    "simulator",
    "adapter",
    "subsystem",
    "validation",
    "interface",
    "integration",
)

_ABSTRACT_SUPPORT_DECOMPOSITION_KINDS = (
    "commercial_component_selection",
    "fixture_harness_or_procedure",
    "validation_fixture_linkage",
    "risk_control_linkage",
    "software_or_interface_contract",
)


def _requested_row_identity_text(row: Mapping[str, Any]) -> str:
    parts: list[str] = []
    for key in (
        "requested_row_id",
        "target_row_id",
        "design_artifact_row_id",
        "target_role",
        "name",
        "category",
        "required_for",
        "source_query_hint",
        "source_acceptance_contract",
        "proposed_subsystem_requirement",
    ):
        value = row.get(key)
        if isinstance(value, list):
            parts.extend(str(item or "") for item in value)
        else:
            parts.append(str(value or ""))
    return re.sub(r"\s+", " ", " ".join(part for part in parts if part)).strip()


def _requested_row_is_abstract_lane(row: Mapping[str, Any]) -> bool:
    if str(row.get("decomposed_from_requested_row_id", "") or "").strip():
        return False
    lane_kind = str(row.get("engineering_obligation_kind", "") or row.get("abstract_lane_kind", "") or "").strip()
    if lane_kind in set(_ABSTRACT_SUPPORT_DECOMPOSITION_KINDS):
        return False
    requested_row_id = str(row.get("requested_row_id", "") or "").strip()
    if any(f"__{kind}" in requested_row_id for kind in _ABSTRACT_SUPPORT_DECOMPOSITION_KINDS):
        return False
    text = _requested_row_identity_text(row).lower()
    return bool(text and any(term in text for term in _ABSTRACT_SUPPORT_LANE_TERMS))


def _context_requests_abstract_lane_decomposition(context: Mapping[str, Any]) -> bool:
    if bool(context.get("abstract_lane_decomposition_required", False)):
        return True
    text = " ".join(
        str(context.get(key, "") or "")
        for key in (
            "provider_blocker",
            "support_provider_quality_blocker",
            "trusted_source_rejection_reason",
            "trusted_source_failure_class",
        )
    ).lower()
    if "missing_source_candidates" in text:
        return True
    source_backed_recovery = (
        "source_backed_rows_required" in text
        or "commercial_source_acquisition_required" in text
        or bool(context.get("commercial_source_acquisition_required", False))
        or bool(context.get("source_backed_rows_required", False))
    )
    next_recovery_action = str(context.get("next_support_recovery_action", "") or "").strip()
    if next_recovery_action not in {
        "conveyor_support_synthesis_job",
        "narrow_research_source_lanes",
        "run_provider_field_lane_source_acquisition",
    }:
        return False
    if not source_backed_recovery:
        return False
    return (
        bool(context.get("commercial_source_acquisition_required", False))
        or bool(context.get("source_backed_rows_required", False))
    )


def _decomposed_requested_row_id(base_requested_row_id: str, lane_kind: str) -> str:
    base = re.sub(r"[^a-zA-Z0-9_.:-]+", "_", str(base_requested_row_id or "").strip()).strip("_")
    if not base:
        base = "abstract_requested_row"
    return _truncate(f"{base}__{lane_kind}", 120)


def _source_hint_for_decomposed_lane(
    row: Mapping[str, Any],
    *,
    lane_kind: str,
    target_artifact: str,
    directive_family: str,
) -> str:
    identity = _requested_row_identity_text(row)
    normalized = re.sub(r"[\s_:#/\\-]+", " ", identity.lower()).strip()
    generic_terms = {
        "commercial_component_selection": "manufacturer MPN datasheet rating cost alternatives measurable spec",
        "fixture_harness_or_procedure": "fixture harness procedure wiring calibration measurement pass fail thresholds test equipment",
        "validation_fixture_linkage": "validation fixture linkage verification method pass fail threshold go/no-go",
        "risk_control_linkage": "risk control FMEA hazard mitigation linked BOM verification fixture go/no-go",
        "software_or_interface_contract": "software interface contract protocol adapter integration validation traceability",
        "novel_subsystem_design": "novel subsystem design obligation requirements validation risks",
    }.get(lane_kind, "source-backed engineering evidence")
    expansion = ""
    if lane_kind == "commercial_component_selection" and "signal" in normalized:
        expansion = "arbitrary waveform generator function generator signal source simulator"
    elif lane_kind == "commercial_component_selection" and ("adapter" in normalized or "interface" in normalized):
        expansion = "isolated interface adapter DAQ module evaluation board"
    return _truncate(
        " ".join(
            part
            for part in (
                str(row.get("source_query_hint", "") or ""),
                lane_kind,
                expansion,
                identity,
                target_artifact,
                directive_family,
                generic_terms,
            )
            if str(part or "").strip()
        ),
        280,
    )


def _required_fields_for_decomposed_lane(
    row: Mapping[str, Any],
    *,
    lane_kind: str,
    context_fields: Iterable[str],
) -> list[str]:
    from .support_evidence import normalize_support_field_name

    row_fields = [
        normalize_support_field_name(item)
        for item in list(row.get("required_fields", []) or [])
        if normalize_support_field_name(item)
    ]
    context_normalized = [
        normalize_support_field_name(item)
        for item in list(context_fields or [])
        if normalize_support_field_name(item)
    ]
    if lane_kind == "commercial_component_selection":
        fields = row_fields or context_normalized or [
            "manufacturer",
            "mpn",
            "datasheet_url",
            "electrical_rating",
            "quantity",
            "unit_cost",
            "alternatives",
            "measurable_spec",
            "substitution_allowed",
            "test_equipment",
            "risk_if_missing",
            "validation_fixture_ref",
            "linked_risk_control_ref",
            "standards_assumption",
            "go_no_go_trace",
        ]
    elif lane_kind == "fixture_harness_or_procedure":
        fields = [
            "test_equipment",
            "validation_fixture_ref",
            "measurable_spec",
            "go_no_go_trace",
            "risk_if_missing",
        ]
    elif lane_kind == "validation_fixture_linkage":
        fields = ["validation_fixture_ref", "test_equipment", "measurable_spec", "go_no_go_trace"]
    elif lane_kind == "risk_control_linkage":
        fields = ["linked_risk_control_ref", "risk_if_missing", "go_no_go_trace"]
    elif lane_kind == "software_or_interface_contract":
        fields = ["measurable_spec", "validation_fixture_ref", "go_no_go_trace", "risk_if_missing"]
    else:
        fields = context_normalized or row_fields
    return list(dict.fromkeys(normalize_support_field_name(item) for item in fields if normalize_support_field_name(item)))


def _decompose_abstract_requested_row(
    row: Mapping[str, Any],
    *,
    target_artifact: str,
    directive_family: str,
    context_fields: Iterable[str],
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    base_id = str(row.get("requested_row_id", "") or "").strip()
    identity = _requested_row_identity_text(row)
    lane_kinds = list(_ABSTRACT_SUPPORT_DECOMPOSITION_KINDS[:4])
    normalized_identity = identity.lower()
    if "interface" in normalized_identity or "adapter" in normalized_identity or "integration" in normalized_identity:
        lane_kinds.append("software_or_interface_contract")
    decomposed_rows: list[dict[str, Any]] = []
    for lane_kind in lane_kinds:
        requested_row_id = _decomposed_requested_row_id(base_id, lane_kind)
        decomposed = {
            "requested_row_id": requested_row_id,
            "target_artifact": str(row.get("target_artifact", "") or target_artifact),
            "target_row_id": str(row.get("target_row_id", "") or row.get("design_artifact_row_id", "") or base_id),
            "design_artifact_row_id": str(row.get("design_artifact_row_id", "") or row.get("target_row_id", "") or base_id),
            "target_role": "",
            "required_fields": _required_fields_for_decomposed_lane(
                row,
                lane_kind=lane_kind,
                context_fields=context_fields,
            ),
            "source_query_hint": _source_hint_for_decomposed_lane(
                row,
                lane_kind=lane_kind,
                target_artifact=target_artifact,
                directive_family=directive_family,
            ),
            "source_acceptance_contract": (
                "Return one row bound to this decomposed requested_row_id. Preserve the exact target "
                "artifact, cover the required fields with concrete values, include source/citation or "
                "explicit design-reduction provenance, and grant no execution authority."
            ),
            "engineering_obligation_kind": lane_kind,
            "abstract_lane_kind": lane_kind,
            "decomposed_from_requested_row_id": base_id,
            "commercial_component_source_required": lane_kind == "commercial_component_selection",
            "grants_execution_authority": False,
        }
        decomposed_rows.append(decomposed)
    diagnostic = dict(row)
    diagnostic["abstract_requested_row_decomposed"] = True
    diagnostic["decomposed_requested_row_ids"] = [row["requested_row_id"] for row in decomposed_rows]
    diagnostic["grants_execution_authority"] = False
    return diagnostic, decomposed_rows


def _apply_abstract_lane_decomposition(
    context: Mapping[str, Any],
    requested_rows: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    if not requested_rows or not _context_requests_abstract_lane_decomposition(context):
        return requested_rows, {}
    if list(context.get("support_role_lane_required_roles", []) or []):
        return requested_rows, {}
    uncovered_ids = {
        str(item or "").strip()
        for item in list(context.get("uncovered_requested_row_ids", []) or [])
        if str(item or "").strip()
    }
    if not uncovered_ids:
        raw_request = context.get("provider_field_lane_request", {})
        if isinstance(raw_request, Mapping):
            uncovered_ids = {
                str(item or "").strip()
                for item in list(raw_request.get("uncovered_requested_row_ids", []) or [])
                if str(item or "").strip()
            }
    if not uncovered_ids:
        return requested_rows, {}
    target_artifact = str(context.get("target_artifact", "") or "").strip()
    directive_family = str(context.get("directive_family", "") or "").strip()
    context_fields = list(context.get("missing_fields", []) or [])
    active_rows: list[dict[str, Any]] = []
    decomposed_diagnostics: list[dict[str, Any]] = []
    decomposed_ids: list[str] = []
    abstract_source_ids: list[str] = []
    for row in requested_rows:
        requested_id = str(row.get("requested_row_id", "") or "").strip()
        if requested_id in uncovered_ids and _requested_row_is_abstract_lane(row):
            diagnostic, decomposed_rows = _decompose_abstract_requested_row(
                row,
                target_artifact=target_artifact,
                directive_family=directive_family,
                context_fields=context_fields,
            )
            decomposed_diagnostics.append(diagnostic)
            abstract_source_ids.append(requested_id)
            active_rows.extend(decomposed_rows)
            decomposed_ids.extend(
                str(item.get("requested_row_id", "") or "").strip()
                for item in decomposed_rows
                if str(item.get("requested_row_id", "") or "").strip()
            )
            continue
        active_rows.append(row)
    if not decomposed_ids:
        return requested_rows, {}
    return active_rows[:24], {
        "abstract_lane_decomposition_state": "decomposed",
        "abstract_lane_decomposition_reason": "missing_source_candidates_for_abstract_requested_row",
        "abstract_source_requested_row_ids": list(dict.fromkeys(abstract_source_ids)),
        "abstract_decomposed_requested_row_ids": list(dict.fromkeys(decomposed_ids)),
        "decomposed_requested_row_ids": list(dict.fromkeys(decomposed_ids)),
        "decomposed_abstract_requested_rows": decomposed_diagnostics,
        "abstract_lane_decomposition_active": True,
        "grants_execution_authority": False,
    }


def _abstract_lane_decomposition_meta_from_requested_rows(
    requested_rows: Iterable[Mapping[str, Any]],
) -> dict[str, Any]:
    grouped: dict[str, list[str]] = {}
    for row in requested_rows:
        if not isinstance(row, Mapping):
            continue
        source_id = str(row.get("decomposed_from_requested_row_id", "") or "").strip()
        requested_id = str(row.get("requested_row_id", "") or "").strip()
        if not source_id or not requested_id:
            continue
        grouped.setdefault(source_id, []).append(requested_id)
    if not grouped:
        return {}
    decomposed_ids = [
        requested_id
        for ids in grouped.values()
        for requested_id in ids
        if requested_id
    ]
    return {
        "abstract_lane_decomposition_state": "decomposed",
        "abstract_lane_decomposition_reason": "recovered_from_decomposed_requested_rows",
        "abstract_source_requested_row_ids": list(grouped),
        "abstract_decomposed_requested_row_ids": list(dict.fromkeys(decomposed_ids)),
        "decomposed_requested_row_ids": list(dict.fromkeys(decomposed_ids)),
        "decomposed_abstract_requested_rows": [
            {
                "requested_row_id": source_id,
                "abstract_requested_row_decomposed": True,
                "decomposed_requested_row_ids": list(dict.fromkeys(ids)),
                "grants_execution_authority": False,
            }
            for source_id, ids in grouped.items()
        ],
        "abstract_lane_decomposition_active": True,
        "grants_execution_authority": False,
    }


def _normalize_decomposed_requested_row_contracts(
    requested_rows: Iterable[Mapping[str, Any]],
) -> list[dict[str, Any]]:
    normalized_rows: list[dict[str, Any]] = []
    for row in requested_rows:
        if not isinstance(row, Mapping):
            continue
        updated = dict(row)
        lane_kind = str(
            updated.get("engineering_obligation_kind", "")
            or updated.get("abstract_lane_kind", "")
            or ""
        ).strip()
        if not lane_kind:
            requested_id = str(updated.get("requested_row_id", "") or "")
            for candidate in _ABSTRACT_SUPPORT_DECOMPOSITION_KINDS:
                if f"__{candidate}" in requested_id:
                    lane_kind = candidate
                    break
        if lane_kind in set(_ABSTRACT_SUPPORT_DECOMPOSITION_KINDS):
            updated["engineering_obligation_kind"] = lane_kind
            updated["abstract_lane_kind"] = str(updated.get("abstract_lane_kind", "") or lane_kind)
            updated["required_fields"] = _required_fields_for_decomposed_lane(
                updated,
                lane_kind=lane_kind,
                context_fields=[],
            )
            updated["commercial_component_source_required"] = (
                lane_kind == "commercial_component_selection"
            )
            updated["grants_execution_authority"] = False
        normalized_rows.append(updated)
    return normalized_rows


def _provider_field_lane_request_from_current_context(context: Mapping[str, Any]) -> dict[str, Any]:
    raw_request = context.get("provider_field_lane_request", {})
    provider_field_lane_request = (
        dict(raw_request)
        if isinstance(raw_request, Mapping) and raw_request
        else {}
    )
    if not provider_field_lane_request:
        return _provider_field_lane_request_for_context(context)
    provider_field_lane_request["requested_rows"] = _normalize_decomposed_requested_row_contracts(
        list(provider_field_lane_request.get("requested_rows", []) or [])
    )
    decomposition_contract_active = bool(
        str(provider_field_lane_request.get("abstract_lane_decomposition_state", "") or "").strip()
    )
    if not decomposition_contract_active:
        inferred_meta = _abstract_lane_decomposition_meta_from_requested_rows(
            list(provider_field_lane_request.get("requested_rows", []) or [])
        )
        if inferred_meta:
            provider_field_lane_request.update(inferred_meta)
            decomposition_contract_active = True
            provider_field_lane_request["provider_latest_freshness_state"] = str(
                provider_field_lane_request.get("provider_latest_freshness_state", "")
                or "current_support_request_recovered_abstract_lane_decomposition"
            )
    current_requested_ids = [
        str(row.get("requested_row_id", "") or "").strip()
        for row in list(provider_field_lane_request.get("requested_rows", []) or [])
        if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
    ]
    if current_requested_ids and decomposition_contract_active:
        requested_id_set = set(current_requested_ids)
        decomposed_id_set = {
            str(item or "").strip()
            for item in list(provider_field_lane_request.get("decomposed_requested_row_ids", []) or [])
            if str(item or "").strip()
        }
        accepted_id_set = requested_id_set | decomposed_id_set
        accepted_ids = [
            str(item or "").strip()
            for item in list(provider_field_lane_request.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip() and str(item or "").strip() in accepted_id_set
        ]
        uncovered_ids = [
            str(item or "").strip()
            for item in list(provider_field_lane_request.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip() and str(item or "").strip() in requested_id_set
        ]
        uncovered_ids.extend(
            requested_id
            for requested_id in current_requested_ids
            if requested_id not in set(accepted_ids) and requested_id not in set(uncovered_ids)
        )
        provider_field_lane_request["accepted_requested_row_ids"] = list(dict.fromkeys(accepted_ids))
        provider_field_lane_request["uncovered_requested_row_ids"] = list(dict.fromkeys(uncovered_ids))
    context_uncovered_ids = [
        str(item or "").strip()
        for item in list(context.get("uncovered_requested_row_ids", []) or [])
        if str(item or "").strip()
    ]
    context_requested_row_ids = {
        str(row.get("requested_row_id", "") or "").strip()
        for row in list(context.get("requested_rows", []) or [])
        if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
    }
    missing_current_uncovered_ids = [
        requested_id
        for requested_id in context_uncovered_ids
        if requested_id in context_requested_row_ids and requested_id not in set(current_requested_ids)
    ]
    if missing_current_uncovered_ids:
        rebuilt_context = dict(context)
        rebuilt_context["provider_field_lane_request"] = {}
        rebuilt = _provider_field_lane_request_for_context(rebuilt_context)
        raw_rows_by_id = {
            str(row.get("requested_row_id", "") or "").strip(): dict(row)
            for row in list(provider_field_lane_request.get("requested_rows", []) or [])
            if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
        }
        merged_rows: list[dict[str, Any]] = []
        for row in list(rebuilt.get("requested_rows", []) or []):
            if not isinstance(row, Mapping):
                continue
            requested_id = str(row.get("requested_row_id", "") or "").strip()
            if not requested_id:
                continue
            decomposed_from_id = str(row.get("decomposed_from_requested_row_id", "") or "").strip()
            if requested_id not in set(context_uncovered_ids) and decomposed_from_id not in set(context_uncovered_ids):
                continue
            merged = dict(row)
            if requested_id in raw_rows_by_id:
                merged.update(
                    {
                        key: value
                        for key, value in raw_rows_by_id[requested_id].items()
                        if value not in (None, "", [], {})
                    }
                )
                merged["requested_row_id"] = requested_id
            merged["target_artifact"] = str(
                merged.get("target_artifact", "") or merge_context.get("target_artifact", "") or ""
            )
            merged["grants_execution_authority"] = False
            merged_rows.append(merged)
        merged_ids = {
            str(row.get("requested_row_id", "") or "").strip()
            for row in merged_rows
            if str(row.get("requested_row_id", "") or "").strip()
        }
        for requested_id, row in raw_rows_by_id.items():
            if requested_id not in merged_ids and requested_id in set(context_uncovered_ids):
                merged = dict(row)
                merged["grants_execution_authority"] = False
                merged_rows.append(merged)
                merged_ids.add(requested_id)
        accepted_ids = [
            str(item or "").strip()
            for item in list(provider_field_lane_request.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        accepted_set = set(accepted_ids)
        uncovered_ids = [
            str(item or "").strip()
            for item in context_uncovered_ids
            if str(item or "").strip()
            and str(item or "").strip() in merged_ids
            and str(item or "").strip() not in accepted_set
        ]
        for requested_id in merged_ids:
            if requested_id not in accepted_set and requested_id not in set(uncovered_ids):
                uncovered_ids.append(requested_id)
        merged_request = dict(rebuilt)
        merged_request.update(
            {
                "requested_rows": merged_rows,
                "requested_row_count": len(merged_rows),
                "accepted_requested_row_ids": list(dict.fromkeys(accepted_ids)),
                "uncovered_requested_row_ids": list(dict.fromkeys(uncovered_ids)),
                "provider_field_lane_rebuilt_from_stale_request_id": str(
                    provider_field_lane_request.get("provider_field_lane_request_id", "") or ""
                ),
                "provider_latest_freshness_state": (
                    "current_support_request_merged_with_uncovered_requested_rows"
                ),
                "grants_execution_authority": False,
            }
        )
        merged_request["provider_field_lane_rebuilt_missing_requested_row_ids"] = (
            missing_current_uncovered_ids
        )
        merged_request["provider_field_lane_request_id"] = _record_id(
            "provider-field-lane",
            merged_request,
        )
        return merged_request
    merge_context = dict(context)
    for key in (
        "support_request_id",
        "directive_id",
        "directive_family",
        "target_artifact",
        "requested_rows",
        "accepted_requested_row_ids",
        "uncovered_requested_row_ids",
        "missing_fields",
    ):
        value = merge_context.get(key)
        if value in (None, "", []) and provider_field_lane_request.get(key) not in (None, "", []):
            merge_context[key] = provider_field_lane_request.get(key)
    if (
        str(provider_field_lane_request.get("support_request_id", "") or "").strip()
        == str(merge_context.get("support_request_id", "") or "").strip()
    ):
        for coverage_key in ("accepted_requested_row_ids", "uncovered_requested_row_ids"):
            provider_value = provider_field_lane_request.get(coverage_key)
            if isinstance(provider_value, list) and provider_value:
                merge_context[coverage_key] = list(provider_value)
        if bool(provider_field_lane_request.get("commercial_component_source_required", False)):
            merge_context.setdefault("commercial_source_acquisition_required", True)
            merge_context.setdefault("source_backed_rows_required", True)
            accepted_ids = [
                str(item or "").strip()
                for item in list(provider_field_lane_request.get("accepted_requested_row_ids", []) or [])
                if str(item or "").strip()
            ]
            uncovered_ids = [
                str(item or "").strip()
                for item in list(provider_field_lane_request.get("uncovered_requested_row_ids", []) or [])
                if str(item or "").strip()
            ]
            if accepted_ids and uncovered_ids:
                merge_context["next_support_recovery_action"] = "narrow_research_source_lanes"
    if (
        _context_requests_abstract_lane_decomposition(merge_context)
        and not str(provider_field_lane_request.get("abstract_lane_decomposition_state", "") or "").strip()
    ):
        rebuilt = _provider_field_lane_request_for_context(merge_context)
        if str(rebuilt.get("abstract_lane_decomposition_state", "") or "") == "decomposed":
            rebuilt["provider_field_lane_rebuilt_from_stale_request_id"] = str(
                provider_field_lane_request.get("provider_field_lane_request_id", "") or ""
            )
            rebuilt["provider_latest_freshness_state"] = "current_support_request_rebuilt_for_abstract_lane_decomposition"
            return rebuilt
    return provider_field_lane_request


def _provider_requested_rows_for_context(context: Mapping[str, Any]) -> list[dict[str, Any]]:
    from .support_evidence import ROLE_LANE_COMPONENT_REQUIRED_FIELDS, normalize_support_field_name, normalize_support_role_lane

    target_artifact = str(context.get("target_artifact", "") or "").strip()
    directive_id = str(context.get("directive_id", "") or "").strip()
    support_request_id = str(context.get("support_request_id", "") or "").strip()
    requested_rows: list[dict[str, Any]] = []
    required_roles = [
        normalize_support_role_lane(item)
        for item in list(context.get("support_role_lane_required_roles", []) or [])
        if normalize_support_role_lane(item)
    ]
    required_roles = list(dict.fromkeys(required_roles))
    explicit_requested_rows = [
        dict(row)
        for row in list(context.get("requested_rows", []) or [])
        if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
    ]
    if explicit_requested_rows:
        context_required_fields = [
            normalize_support_field_name(item)
            for item in list(context.get("missing_fields", []) or [])
            if normalize_support_field_name(item)
        ]
        if required_roles:
            context_required_fields.extend(
                normalize_support_field_name(item)
                for item in ROLE_LANE_COMPONENT_REQUIRED_FIELDS
                if normalize_support_field_name(item)
            )
        for row in explicit_requested_rows:
            row["target_artifact"] = str(row.get("target_artifact", "") or target_artifact)
            row_fields = [
                normalize_support_field_name(item)
                for item in list(row.get("required_fields", []) or [])
                if normalize_support_field_name(item)
            ]
            row["required_fields"] = list(dict.fromkeys(row_fields + context_required_fields))
            row["grants_execution_authority"] = False
        return explicit_requested_rows[:12]
    if required_roles:
        role_fields = [
            normalize_support_field_name(item)
            for item in ROLE_LANE_COMPONENT_REQUIRED_FIELDS
            if normalize_support_field_name(item)
        ]
        for role in required_roles:
            requested_rows.append(
                {
                    "requested_row_id": _provider_requested_row_id(
                        support_request_id,
                        directive_id,
                        target_artifact,
                        role,
                    ),
                    "target_artifact": target_artifact,
                    "target_role": role,
                    "target_row_id": role,
                    "required_fields": role_fields,
                    "source_query_hint": _truncate(
                        (
                            f"{role} {target_artifact} manufacturer MPN datasheet rating quantity cost "
                            "alternatives measurable spec substitution test equipment risk-if-missing "
                            "fixture risk standards go/no-go"
                        ),
                        260,
                    ),
                    "source_acceptance_contract": (
                        "Return one concrete source-backed component row for this exact role lane with "
                        "manufacturer, MPN, datasheet/source URL, rating, quantity, cost basis, alternatives, "
                        "measurable spec, substitution rule, test equipment, risk-if-missing, fixture link, "
                        "risk link, standards assumption, and go/no-go trace."
                    ),
                    "commercial_component_source_required": True,
                    "grants_execution_authority": False,
                }
            )
        return requested_rows

    if target_artifact == "risk_controls.json":
        risk_fields = _risk_control_required_fields()
        design_rows_by_id = {
            str(
                row.get("target_row_id", "")
                or row.get("control_id", "")
                or row.get("hazard_id", "")
                or row.get("row_id", "")
                or row.get("item_id", "")
                or ""
            ).strip(): dict(row)
            for row in _context_design_artifact_rows(context)
            if str(
                row.get("target_row_id", "")
                or row.get("control_id", "")
                or row.get("hazard_id", "")
                or row.get("row_id", "")
                or row.get("item_id", "")
                or ""
            ).strip()
        }
        refs = [
            str(item or "").strip()
            for item in list(context.get("missing_fmea_row_refs", []) or context.get("linked_bom_refs", []) or [])
            if str(item or "").strip()
        ]
        if not refs:
            refs = list(design_rows_by_id) or ["risk_control_chain"]
        for ref in list(dict.fromkeys(refs))[:12]:
            ref_tail = ref.split("#")[-1].strip()
            design_row = design_rows_by_id.get(ref) or design_rows_by_id.get(ref_tail) or {}
            design_artifact_row_id = str(
                design_row.get("target_row_id", "")
                or design_row.get("control_id", "")
                or design_row.get("hazard_id", "")
                or design_row.get("row_id", "")
                or design_row.get("item_id", "")
                or ""
            ).strip()
            requested_rows.append(
                {
                    "requested_row_id": _provider_requested_row_id(
                        support_request_id,
                        directive_id,
                        target_artifact,
                        ref,
                    ),
                    "target_artifact": target_artifact,
                    "target_row_id": ref,
                    "required_fields": risk_fields,
                    "design_artifact_row_id": design_artifact_row_id,
                    "source_query_hint": _truncate(
                        " ".join(
                            part
                            for part in (
                                ref,
                                str(design_row.get("failure_mode", "") or ""),
                                str(design_row.get("effect", "") or ""),
                                str(design_row.get("linked_bom_ref", "") or ""),
                                str(design_row.get("verification_fixture_ref", "") or ""),
                                "FMEA hazard failure mode mitigation verification go/no-go criteria",
                            )
                            if part
                        ),
                        260,
                    ),
                    "source_acceptance_contract": (
                        "Return one FMEA-like review-only risk row with hazard, failure mode, effect, "
                        "severity, occurrence, detectability, mitigation, linked BOM ref, verification "
                        "fixture ref, and go/no-go criteria."
                    ),
                    "commercial_component_source_required": False,
                    "grants_execution_authority": False,
                }
            )
        return requested_rows

    if target_artifact == "validation_fixtures.json":
        fixture_fields = _validation_fixture_required_fields()
        design_rows_by_id = {
            str(
                row.get("target_row_id", "")
                or row.get("fixture_id", "")
                or row.get("row_id", "")
                or row.get("item_id", "")
                or ""
            ).strip(): dict(row)
            for row in _context_design_artifact_rows(context)
            if str(
                row.get("target_row_id", "")
                or row.get("fixture_id", "")
                or row.get("row_id", "")
                or row.get("item_id", "")
                or ""
            ).strip()
        }
        refs = [
            str(item or "").strip()
            for item in list(context.get("missing_validation_fixture_refs", []) or [])
            if str(item or "").strip()
        ]
        if not refs:
            refs = list(design_rows_by_id) or ["validation_fixture_chain"]
        for ref in list(dict.fromkeys(refs))[:12]:
            ref_tail = ref.split("#")[-1].split(":")[-1].strip()
            full_ref = ref if "#" in ref else f"validation_fixtures.json#{ref_tail}"
            design_row = design_rows_by_id.get(ref) or design_rows_by_id.get(ref_tail) or design_rows_by_id.get(full_ref) or {}
            linked_bom_refs = design_row.get("linked_bom_refs", [])
            if not isinstance(linked_bom_refs, list):
                linked_bom_refs = [linked_bom_refs] if str(linked_bom_refs or "").strip() else []
            linked_risk_refs = design_row.get("linked_risk_control_refs", [])
            if not isinstance(linked_risk_refs, list):
                linked_risk_refs = [linked_risk_refs] if str(linked_risk_refs or "").strip() else []
            requested_rows.append(
                {
                    "requested_row_id": _provider_requested_row_id(
                        support_request_id,
                        directive_id,
                        target_artifact,
                        full_ref,
                    ),
                    "target_artifact": target_artifact,
                    "target_row_id": full_ref,
                    "target_fixture_ref": ref_tail,
                    "required_fields": fixture_fields,
                    "design_artifact_row_id": str(
                        design_row.get("target_row_id", "")
                        or design_row.get("fixture_id", "")
                        or design_row.get("row_id", "")
                        or ""
                    ).strip(),
                    "linked_bom_refs": [str(item) for item in linked_bom_refs if str(item).strip()],
                    "linked_risk_control_refs": [
                        str(item) for item in linked_risk_refs if str(item).strip()
                    ],
                    "source_query_hint": _truncate(
                        " ".join(
                            part
                            for part in (
                                ref_tail,
                                " ".join(str(item) for item in linked_bom_refs if str(item).strip()),
                                " ".join(str(item) for item in linked_risk_refs if str(item).strip()),
                                "validation fixture equipment wiring calibration measurement method pass/fail thresholds execution gate",
                            )
                            if part
                        ),
                        320,
                    ),
                    "source_acceptance_contract": (
                        "Return one review-only validation fixture row bound to this requested_row_id "
                        "with equipment, fixture wiring, calibration steps, measurement method, "
                        "pass/fail thresholds, linked BOM refs, linked risk-control refs, execution gate, "
                        "source/citation or explicit design-reduction provenance, and no execution authority."
                    ),
                    "commercial_component_source_required": False,
                    "source_backed_fixture_required": True,
                    "grants_execution_authority": False,
                }
            )
        return requested_rows

    design_rows = _context_design_artifact_rows(context)
    if target_artifact == "bill_of_materials.json" and design_rows:
        bom_fields = _build_grade_bom_required_fields(context)
        for index, design_row in enumerate(design_rows[:12]):
            target_row_id = _artifact_row_identity(design_row, fallback_prefix="bom_design_row", index=index)
            search_needs = design_row.get("source_search_needs")
            if isinstance(search_needs, list):
                hint_needs = " ".join(str(item) for item in search_needs if str(item).strip())
            else:
                hint_needs = str(search_needs or "")
            requested_rows.append(
                {
                    "requested_row_id": _provider_requested_row_id(
                        support_request_id,
                        directive_id,
                        target_artifact,
                        target_row_id,
                    ),
                    "target_artifact": target_artifact,
                    "target_row_id": target_row_id,
                    "required_fields": bom_fields,
                    "source_query_hint": _truncate(
                        " ".join(
                            part
                            for part in (
                                target_row_id,
                                str(design_row.get("name", "") or ""),
                                str(design_row.get("category", "") or ""),
                                str(design_row.get("required_for", "") or ""),
                                str(design_row.get("proposed_subsystem_requirement", "") or ""),
                                hint_needs,
                                "manufacturer MPN datasheet rating quantity cost fixture risk standards alternatives measurable spec test equipment",
                            )
                            if part
                        ),
                        420,
                    ),
                    "source_acceptance_contract": (
                        "Return one concrete source-backed BOM row for this design obligation with "
                        "manufacturer, MPN, datasheet URL, electrical rating, quantity, unit cost or cost "
                        "basis, validation fixture ref, linked risk control ref, standards assumption, "
                        "alternatives where applicable, measurable spec, test equipment, and risk-if-missing."
                    ),
                    "design_artifact_row_id": target_row_id,
                    "commercial_component_source_required": True,
                    "grants_execution_authority": False,
                }
            )
        return requested_rows

    fallback_fields = [
        normalize_support_field_name(item)
        for item in list(context.get("missing_fields", []) or [])
        if normalize_support_field_name(item)
    ]
    if not fallback_fields and target_artifact == "bill_of_materials.json":
        fallback_fields = _build_grade_bom_required_fields(context)
    if fallback_fields:
        requested_rows.append(
            {
                "requested_row_id": _provider_requested_row_id(
                    support_request_id,
                    directive_id,
                    target_artifact,
                    "artifact_field_gap",
                ),
                "target_artifact": target_artifact,
                "target_row_id": "artifact_field_gap",
                "required_fields": list(dict.fromkeys(fallback_fields)),
                "source_query_hint": _truncate(
                    f"{target_artifact} " + " ".join(list(dict.fromkeys(fallback_fields))),
                    260,
                ),
                "source_acceptance_contract": (
                    "Return one or more concrete source-backed rows bound to this requested_row_id and "
                    "covering every required field."
                ),
                "commercial_component_source_required": True,
                "grants_execution_authority": False,
            }
        )
    return requested_rows


def _provider_field_lane_request_for_context(context: Mapping[str, Any]) -> dict[str, Any]:
    from .support_evidence import normalize_support_field_name, normalize_support_role_lane

    required_fields = [
        normalize_support_field_name(item)
        for item in list(context.get("missing_fields", []) or [])
        if normalize_support_field_name(item)
    ]
    required_fields = list(dict.fromkeys(required_fields))
    required_roles = [
        normalize_support_role_lane(item)
        for item in list(context.get("support_role_lane_required_roles", []) or [])
        if normalize_support_role_lane(item)
    ]
    required_roles = list(dict.fromkeys(required_roles))
    requested_rows = _provider_requested_rows_for_context(context)
    requested_rows, decomposition_meta = _apply_abstract_lane_decomposition(context, requested_rows)
    requested_row_ids = [
        str(row.get("requested_row_id", "") or "")
        for row in requested_rows
        if str(row.get("requested_row_id", "") or "")
    ]
    accepted_requested_row_ids = [
        str(item or "").strip()
        for item in list(
            context.get("accepted_requested_row_ids", [])
            or dict(context.get("provider_field_lane_request", {}) or {}).get("accepted_requested_row_ids", [])
            or []
        )
        if str(item or "").strip() and str(item or "").strip() in set(requested_row_ids)
    ]
    explicit_uncovered = [
        str(item or "").strip()
        for item in list(
            decomposition_meta.get("decomposed_requested_row_ids", [])
            or context.get("uncovered_requested_row_ids", [])
            or dict(context.get("provider_field_lane_request", {}) or {}).get("uncovered_requested_row_ids", [])
            or []
        )
        if str(item or "").strip()
    ]
    active_requested_row_ids = set(requested_row_ids)
    uncovered_requested_row_ids = [
        item for item in explicit_uncovered if item in active_requested_row_ids and item not in set(accepted_requested_row_ids)
    ]
    if not uncovered_requested_row_ids:
        uncovered_requested_row_ids = [
            item for item in requested_row_ids if item not in set(accepted_requested_row_ids)
        ]
    design_row_ids = [
        str(row.get("design_artifact_row_id", "") or row.get("target_row_id", "") or "")
        for row in requested_rows
        if str(row.get("design_artifact_row_id", "") or "")
    ]
    request: dict[str, Any] = {
        "schema_name": "ProviderFieldLaneRequest",
        "schema_version": AUTONOMY_SCHEMA_VERSION,
        "created_at": _now(),
        "provider_field_lane_request_id": "",
        "support_request_id": str(context.get("support_request_id", "") or ""),
        "directive_id": str(context.get("directive_id", "") or ""),
        "directive_family": str(context.get("directive_family", "") or ""),
        "target_artifact": str(context.get("target_artifact", "") or ""),
        "required_fields": required_fields,
        "required_roles": required_roles,
        "requested_rows": requested_rows,
        "requested_row_count": len(requested_rows) or max(1, len(required_roles) or len(required_fields) or 1),
        "accepted_requested_row_ids": accepted_requested_row_ids,
        "uncovered_requested_row_ids": uncovered_requested_row_ids,
        "rejected_requested_rows": [],
        "source_acquisition_from_design_row_ids": list(dict.fromkeys(design_row_ids)),
        "commercial_component_source_required": True,
        "child_work_mode": str(context.get("child_work_mode", "") or ""),
        "grants_execution_authority": False,
    }
    if decomposition_meta:
        request.update(decomposition_meta)
    request["provider_field_lane_request_id"] = _record_id("provider-field-lane", request)
    return request


def _provider_field_lane_request_subset(
    provider_field_lane_request: Mapping[str, Any],
    requested_row_ids: Iterable[Any],
) -> dict[str, Any]:
    selected_ids = {
        str(item or "").strip()
        for item in requested_row_ids
        if str(item or "").strip()
    }
    if not selected_ids:
        return dict(provider_field_lane_request)
    request = dict(provider_field_lane_request)
    requested_rows = [
        dict(row)
        for row in list(provider_field_lane_request.get("requested_rows", []) or [])
        if isinstance(row, Mapping)
        and str(row.get("requested_row_id", "") or "").strip() in selected_ids
    ]
    if not requested_rows:
        return request
    request["requested_rows"] = requested_rows
    request["requested_row_count"] = len(requested_rows)
    request["uncovered_requested_row_ids"] = [
        str(row.get("requested_row_id", "") or "").strip()
        for row in requested_rows
        if str(row.get("requested_row_id", "") or "").strip()
    ]
    request["accepted_requested_row_ids"] = [
        str(item or "").strip()
        for item in list(provider_field_lane_request.get("accepted_requested_row_ids", []) or [])
        if str(item or "").strip() and str(item or "").strip() not in selected_ids
    ]
    request["provider_field_lane_retry_scope"] = "uncovered_requested_rows"
    request["provider_field_lane_retry_original_request_id"] = str(
        provider_field_lane_request.get("provider_field_lane_request_id", "") or ""
    )
    return request


def _validate_directive_build_grade_support_structured(
    structured: Mapping[str, Any],
    *,
    context: Mapping[str, Any],
) -> tuple[dict[str, Any], str]:
    from .support_evidence import assess_component_selection_rows, normalize_support_field_name, normalize_support_role_lane

    target_artifact = str(
        context.get("target_artifact")
        or structured.get("target_artifact")
        or ""
    ).strip()
    missing_fields = {
        normalize_support_field_name(item)
        for item in list(context.get("missing_fields", []) or [])
        if normalize_support_field_name(item)
    }
    required_roles = {
        normalize_support_role_lane(item)
        for item in list(context.get("support_role_lane_required_roles", []) or [])
        if normalize_support_role_lane(item)
    }
    source_plan = dict(context.get("source_plan", {}) or {})
    source_candidates = {
        str(row.get("source_candidate_id", "") or ""): dict(row)
        for row in list(source_plan.get("source_candidates", []) or [])
        if isinstance(row, Mapping) and str(row.get("source_candidate_id", "") or "")
    }
    raw_field_lane_request = context.get("provider_field_lane_request", {})
    provider_field_lane_request = (
        dict(raw_field_lane_request)
        if isinstance(raw_field_lane_request, Mapping)
        else _provider_field_lane_request_for_context(context)
    )
    if not provider_field_lane_request:
        provider_field_lane_request = _provider_field_lane_request_for_context(context)
    provider_field_lane_request = _provider_field_lane_request_from_current_context(
        {
            **dict(context),
            "provider_field_lane_request": provider_field_lane_request,
        }
    )
    requested_rows = [
        dict(item)
        for item in list(provider_field_lane_request.get("requested_rows", []) or [])
        if isinstance(item, Mapping)
    ]
    requested_by_id = {
        str(item.get("requested_row_id", "") or ""): item
        for item in requested_rows
        if str(item.get("requested_row_id", "") or "")
    }
    accepted_requested_row_ids: list[str] = []
    rejected_requested_rows: list[dict[str, Any]] = []
    rows: list[dict[str, Any]] = []
    rejected: list[str] = []
    for index, item in enumerate(list(structured.get("child_support_rows", []) or [])[:12]):
        row = dict(item) if isinstance(item, Mapping) else {}
        row_id = _truncate(str(row.get("row_id", "") or f"support_row_{index + 1}").strip(), 100)
        requested_row_id = _truncate(str(row.get("requested_row_id", "") or "").strip(), 120)
        row_target = _truncate(str(row.get("target_artifact", "") or "").strip(), 160)
        claim = _truncate(str(row.get("claim", "") or "").strip(), 420)
        covered_fields = [
            normalize_support_field_name(item)
            for item in _bounded_string_list(row.get("covered_fields", []), limit=16, item_limit=80)
            if normalize_support_field_name(item)
        ]
        covered_fields = list(dict.fromkeys(covered_fields))
        spec_values = _normalize_build_grade_spec_values(
            row.get("spec_values") or row.get("concrete_spec_values")
        )
        for spec_value in spec_values:
            key_text = str(spec_value).split("=", 1)[0].strip() if "=" in str(spec_value) else ""
            normalized_key = normalize_support_field_name(key_text)
            if normalized_key and normalized_key not in covered_fields:
                covered_fields.append(normalized_key)
        for key in (
            "manufacturer",
            "supplier",
            "mpn",
            "part_number",
            "datasheet",
            "datasheet_url",
            "electrical_rating",
            "rating",
            "quantity",
            "unit_cost",
            "cost_basis",
            "validation_fixture_ref",
            "fixture_ref",
            "linked_risk_control_ref",
            "risk_ref",
            "standards_assumption",
            "standards",
            "go_no_go_trace",
            "go_no_go_criteria",
        ):
            if str(row.get(key, "") or "").strip():
                normalized_key = normalize_support_field_name(key)
                if normalized_key and normalized_key not in covered_fields:
                    covered_fields.append(normalized_key)
        source_url = _truncate(str(row.get("source_url", "") or row.get("url", "") or "").strip(), 300)
        citation_ref = _truncate(str(row.get("citation_ref", "") or "").strip(), 300)
        evidence_ref = _truncate(str(row.get("evidence_ref", "") or "").strip(), 160)
        source_candidate_id = _truncate(str(row.get("source_candidate_id", "") or "").strip(), 100)
        target_role = _truncate(str(row.get("target_role", "") or row.get("role", "") or "").strip(), 120)
        normalized_target_role = normalize_support_role_lane(target_role)
        source_candidate = source_candidates.get(source_candidate_id, {})
        if source_candidate and not source_url:
            source_url = _truncate(str(source_candidate.get("source_url", "") or "").strip(), 300)
        if source_candidate and not citation_ref:
            citation_ref = _truncate(str(source_candidate.get("citation_ref", "") or "").strip(), 300)
        row_rejections: list[str] = []
        if not row_id:
            row_rejections.append("missing_row_id")
        if target_artifact and row_target != target_artifact:
            row_rejections.append("target_artifact_mismatch")
        if not claim:
            row_rejections.append("missing_claim")
        if not covered_fields:
            row_rejections.append("missing_field_coverage")
        if missing_fields and not (set(covered_fields) & missing_fields):
            row_rejections.append("missing_current_required_field_coverage")
        if not spec_values:
            row_rejections.append("missing_spec_values")
        if not (
            _build_grade_source_is_concrete(source_url)
            or _build_grade_source_is_concrete(citation_ref)
        ):
            row_rejections.append("missing_concrete_source_url_or_citation")
        if source_candidates and not source_candidate_id:
            row_rejections.append("missing_source_candidate_id")
        if source_candidates and source_candidate_id and source_candidate_id not in source_candidates:
            row_rejections.append("unknown_source_candidate_id")
        if required_roles and not normalized_target_role:
            row_rejections.append("missing_target_role")
        if required_roles and normalized_target_role and normalized_target_role not in required_roles:
            row_rejections.append("target_role_not_required")
        requested_contract: Mapping[str, Any] = {}
        if requested_by_id:
            if not requested_row_id:
                row_rejections.append("missing_requested_row_id")
            elif requested_row_id not in requested_by_id:
                row_rejections.append("unknown_requested_row_id")
            else:
                requested_contract = requested_by_id[requested_row_id]
                requested_target = str(requested_contract.get("target_artifact", "") or "").strip()
                if requested_target and row_target != requested_target:
                    row_rejections.append("requested_row_target_mismatch")
                requested_role = normalize_support_role_lane(
                    requested_contract.get("target_role", "") or requested_contract.get("role", "")
                )
                if requested_role and normalized_target_role != requested_role:
                    row_rejections.append("requested_row_role_mismatch")
                requested_fields = {
                    normalize_support_field_name(field)
                    for field in list(requested_contract.get("required_fields", []) or [])
                    if normalize_support_field_name(field)
                }
                missing_requested_fields = sorted(requested_fields - set(covered_fields))
                if missing_requested_fields:
                    row_rejections.append(
                        "missing_requested_row_fields:" + ",".join(missing_requested_fields[:8])
                    )
        if not evidence_ref:
            row_rejections.append("missing_evidence_ref")
        if bool(row.get("grants_execution_authority", False)):
            row_rejections.append("grants_execution_authority_not_allowed")
        if row_rejections:
            rejected.extend(row_rejections)
            if requested_row_id:
                rejected_requested_rows.append(
                    {
                        "requested_row_id": requested_row_id,
                        "row_id": row_id,
                        "rejected_reasons": list(dict.fromkeys(row_rejections)),
                    }
                )
            continue
        if requested_row_id and requested_row_id not in accepted_requested_row_ids:
            accepted_requested_row_ids.append(requested_row_id)
        rows.append(
            {
                "row_id": row_id,
                "requested_row_id": requested_row_id,
                "target_row_id": str(requested_contract.get("target_row_id", "") or row.get("target_row_id", "") or ""),
                "design_artifact_row_id": str(
                    requested_contract.get("design_artifact_row_id", "")
                    or row.get("design_artifact_row_id", "")
                    or ""
                ),
                "target_artifact": row_target,
                "target_role": normalized_target_role or target_role,
                "covered_fields": covered_fields,
                "required_fields": covered_fields,
                "claim": claim,
                "spec_values": spec_values,
                "source_url": source_url,
                "citation_ref": citation_ref,
                "source_hint": source_url or citation_ref,
                "evidence_ref": evidence_ref,
                "source_candidate_id": source_candidate_id,
                "relevance": _truncate(str(row.get("relevance", "") or f"Supports {row_target}.").strip(), 240),
                "grants_execution_authority": False,
            }
        )
    component_assessment: dict[str, Any] = {}
    if required_roles:
        component_assessment = assess_component_selection_rows(
            rows,
            required_roles=sorted(required_roles),
            target_artifact=target_artifact,
        )
        missing_roles = list(component_assessment.get("support_role_lane_uncovered_roles", []) or [])
        if missing_roles:
            rejected.append("missing_required_role_lanes:" + ",".join(missing_roles))
        component_reasons = list(component_assessment.get("component_selection_rejected_row_reasons", []) or [])
        if component_reasons:
            rejected.extend(component_reasons[:8])
        if (
            (missing_roles or str(component_assessment.get("component_selection_workbench_state", "") or "") == "rejected")
            and not rows
        ):
            return {}, "candidate_rejected:" + ",".join(sorted(set(rejected))[:8])
    if not rows:
        reason = "missing_child_support_rows"
        if rejected:
            reason = "candidate_rejected:" + ",".join(sorted(set(rejected))[:8])
        return {}, reason
    uncovered_requested_row_ids = [
        requested_row_id
        for requested_row_id in requested_by_id
        if requested_row_id not in set(accepted_requested_row_ids)
    ]
    if uncovered_requested_row_ids:
        rejected.append("uncovered_requested_rows:" + ",".join(uncovered_requested_row_ids[:8]))
        return {
            "digest_status": str(structured.get("digest_status", "") or "partial"),
            "support_request_id": str(structured.get("support_request_id", "") or context.get("support_request_id", "")),
            "directive_id": str(structured.get("directive_id", "") or context.get("directive_id", "")),
            "target_artifact": target_artifact,
            "provider_field_lane_request": provider_field_lane_request,
            "provider_field_lane_request_id": str(
                provider_field_lane_request.get("provider_field_lane_request_id", "")
                or context.get("provider_field_lane_request_id", "")
                or ""
            ),
            "child_support_rows": rows,
            "child_support_row_count": len(rows),
            "component_selection_workbench_state": str(
                component_assessment.get("component_selection_workbench_state", "not_required") or "not_required"
            ),
            "component_selection_rejected_row_reasons": list(
                component_assessment.get("component_selection_rejected_row_reasons", []) or []
            ),
            "support_role_lane_required_roles": list(
                component_assessment.get("support_role_lane_required_roles", []) or sorted(required_roles)
            ),
            "support_role_lane_accepted_rows": list(
                component_assessment.get("support_role_lane_accepted_rows", []) or []
            ),
            "support_role_lane_uncovered_roles": list(
                component_assessment.get("support_role_lane_uncovered_roles", []) or []
            ),
            "accepted_requested_row_ids": accepted_requested_row_ids,
            "uncovered_requested_row_ids": uncovered_requested_row_ids,
            "rejected_requested_rows": rejected_requested_rows,
            "source_acquisition_from_design_row_ids": list(
                provider_field_lane_request.get("source_acquisition_from_design_row_ids", []) or []
            ),
            "field_lane_uncovered_fields": [],
            "field_lane_uncovered_roles": list(
                component_assessment.get("support_role_lane_uncovered_roles", []) or []
            ),
            "support_evidence_contract_passed": False,
            "grants_execution_authority": False,
        }, "candidate_rejected:" + ",".join(sorted(set(rejected))[:8])
    covered_field_set = {
        normalize_support_field_name(item)
        for row in rows
        for item in list(row.get("covered_fields", []) or [])
        if normalize_support_field_name(item)
    }
    required_field_set = set(missing_fields)
    if requested_by_id:
        row_scoped_required_fields = {
            normalize_support_field_name(field)
            for requested_contract in requested_by_id.values()
            for field in list(requested_contract.get("required_fields", []) or [])
            if normalize_support_field_name(field)
        }
        if row_scoped_required_fields:
            required_field_set = row_scoped_required_fields
    uncovered_fields = sorted(required_field_set - covered_field_set)
    if uncovered_fields:
        rejected.append("missing_provider_field_lane_fields:" + ",".join(uncovered_fields[:8]))
        return {}, "candidate_rejected:" + ",".join(sorted(set(rejected))[:8])
    return {
        "digest_status": str(structured.get("digest_status", "") or "completed"),
        "support_request_id": str(structured.get("support_request_id", "") or context.get("support_request_id", "")),
        "directive_id": str(structured.get("directive_id", "") or context.get("directive_id", "")),
        "target_artifact": target_artifact,
        "provider_field_lane_request": provider_field_lane_request,
        "provider_field_lane_request_id": str(
            provider_field_lane_request.get("provider_field_lane_request_id", "")
            or context.get("provider_field_lane_request_id", "")
            or ""
        ),
        "child_support_rows": rows,
        "child_support_row_count": len(rows),
        "relevance_tags": _bounded_string_list(structured.get("relevance_tags", []), item_limit=80),
        "rejected_claims": _bounded_string_list(structured.get("rejected_claims", [])),
        "weak_claims": _bounded_string_list(structured.get("weak_claims", [])),
        "component_selection_workbench_state": str(
            component_assessment.get("component_selection_workbench_state", "not_required") or "not_required"
        ),
        "component_selection_rejected_row_reasons": list(
            component_assessment.get("component_selection_rejected_row_reasons", []) or []
        ),
        "support_role_lane_required_roles": list(
            component_assessment.get("support_role_lane_required_roles", []) or sorted(required_roles)
        ),
        "support_role_lane_accepted_rows": list(
            component_assessment.get("support_role_lane_accepted_rows", []) or []
        ),
        "support_role_lane_uncovered_roles": list(
            component_assessment.get("support_role_lane_uncovered_roles", []) or []
        ),
        "accepted_requested_row_ids": accepted_requested_row_ids,
        "uncovered_requested_row_ids": [],
        "rejected_requested_rows": rejected_requested_rows,
        "source_acquisition_from_design_row_ids": list(
            provider_field_lane_request.get("source_acquisition_from_design_row_ids", []) or []
        ),
        "field_lane_uncovered_fields": [],
        "field_lane_uncovered_roles": list(
            component_assessment.get("support_role_lane_uncovered_roles", []) or []
        ),
        "support_evidence_contract_passed": True,
        "grants_execution_authority": False,
    }, ""


def _directive_support_source_plan(
    operator_root: str | Path,
    *,
    readiness: Mapping[str, Any],
    selected_model: str,
    context: Mapping[str, Any],
) -> dict[str, Any]:
    raw_request = context.get("provider_field_lane_request", {})
    provider_field_lane_request = _provider_field_lane_request_from_current_context(context)
    current_support_request_id = str(
        provider_field_lane_request.get("support_request_id", "")
        or context.get("support_request_id", "")
        or ""
    )
    source_query_generation = _requested_row_source_queries(
        context,
        provider_field_lane_request,
        reason=(
            "narrow_research_source_lanes"
            if str(context.get("next_support_recovery_action", "") or "")
            == "narrow_research_source_lanes"
            else "requested_row_source_query_fallback"
        ),
    )
    source_plan_context = {
        **dict(context),
        "support_request_id": current_support_request_id,
        "current_provider_support_request_id": current_support_request_id,
        "provider_latest_freshness_state": (
            "current_support_request" if current_support_request_id else ""
        ),
        "provider_field_lane_request": provider_field_lane_request,
        **source_query_generation,
    }
    plan: dict[str, Any] = {
        "schema_name": "DirectiveSupportSourcePlan",
        "schema_version": AUTONOMY_SCHEMA_VERSION,
        "created_at": _now(),
        "source_plan_id": "",
        "status": "blocked",
        "support_request_id": current_support_request_id,
        "current_provider_support_request_id": current_support_request_id,
        "provider_latest_freshness_state": (
            "current_support_request" if current_support_request_id else ""
        ),
        "directive_id": str(context.get("directive_id", "") or ""),
        "target_artifact": str(context.get("target_artifact", "") or ""),
        "required_fields": _bounded_string_list(context.get("missing_fields", []), limit=24, item_limit=80),
        "search_queries": list(source_query_generation.get("generated_search_queries", []) or []),
        "source_candidates": [],
        "source_candidate_count": 0,
        "rejected_source_types": [],
        "relevance_tags": [],
        "trusted_source_attempts": [],
        "trusted_source_attempt_count": 0,
        "trusted_source_response_status": "",
        "trusted_source_failure_class": "",
        "trusted_source_rejection_reason": "",
        "provider_blocker": "",
        "provider_field_lane_request": provider_field_lane_request,
        "provider_field_lane_request_id": str(
            provider_field_lane_request.get("provider_field_lane_request_id", "") or ""
        ),
        "requested_rows": list(provider_field_lane_request.get("requested_rows", []) or []),
        "requested_row_count": int(provider_field_lane_request.get("requested_row_count", 0) or 0),
        "abstract_lane_decomposition_state": str(
            provider_field_lane_request.get("abstract_lane_decomposition_state", "") or ""
        ),
        "abstract_lane_decomposition_reason": str(
            provider_field_lane_request.get("abstract_lane_decomposition_reason", "") or ""
        ),
        "abstract_source_requested_row_ids": list(
            provider_field_lane_request.get("abstract_source_requested_row_ids", []) or []
        ),
        "decomposed_requested_row_ids": list(
            provider_field_lane_request.get("decomposed_requested_row_ids", []) or []
        ),
        "decomposed_abstract_requested_rows": list(
            provider_field_lane_request.get("decomposed_abstract_requested_rows", []) or []
        ),
        "grants_execution_authority": False,
        **source_query_generation,
        **_trusted_source_workflow_profile_metadata(),
    }
    attempts: list[dict[str, Any]] = []
    repair_note = ""
    for attempt_number in range(1, TRUSTED_SOURCE_TRIAGE_MAX_ATTEMPTS + 1):
        attempt_meta: dict[str, Any] = {
            "attempt_number": attempt_number,
            "response_status": "",
            "failure_class": "",
            "rejection_reason": "",
            "parse_outcome": "unattempted",
            "accepted": False,
            "source_candidate_count": 0,
        }
        payload = _directive_support_source_plan_payload(
            model=selected_model,
            context=source_plan_context,
            repair_note=repair_note,
        )
        try:
            status_code, response = _trusted_source_external_json_request(
                method="POST",
                endpoint="/responses",
                credential_value=str(readiness.get("credential_value", "")),
                endpoint_base=str(readiness.get("endpoint_base", "")),
                payload=payload,
                timeout_seconds=60,
            )
            attempt_meta["response_status"] = str(status_code)
            plan["trusted_source_response_status"] = str(status_code)
        except GovernedExecutionFailure as exc:
            attempt_meta["failure_class"] = "request_failed"
            attempt_meta["rejection_reason"] = str(exc)
            attempts.append(attempt_meta)
            plan["trusted_source_failure_class"] = "request_failed"
            plan["provider_blocker"] = str(exc)
            break
        if status_code != 200:
            attempt_meta["failure_class"] = "http_status"
            attempt_meta["rejection_reason"] = f"external trusted-source request returned status {status_code}"
            attempts.append(attempt_meta)
            plan["trusted_source_failure_class"] = "http_status"
            plan["provider_blocker"] = str(attempt_meta["rejection_reason"])
            break
        structured, _response_text, parse_outcome = _extract_openai_response_json_with_outcome(response)
        attempt_meta["parse_outcome"] = parse_outcome
        structured = _coerce_source_plan_structured_json(structured, context=context)
        if not isinstance(structured, dict):
            attempt_meta["failure_class"] = "malformed_json"
            attempt_meta["rejection_reason"] = "external trusted-source response was not structured JSON"
            attempts.append(attempt_meta)
            plan["trusted_source_failure_class"] = "malformed_json"
            repair_note = "malformed_json"
            if attempt_number < TRUSTED_SOURCE_TRIAGE_MAX_ATTEMPTS:
                continue
            break
        validated, rejection_reason = _validate_directive_support_source_plan_structured(
            structured,
            context=source_plan_context,
        )
        attempt_meta["source_candidate_count"] = int(validated.get("source_candidate_count", 0) or 0)
        if rejection_reason:
            attempt_meta["failure_class"] = "candidate_rejected"
            attempt_meta["rejection_reason"] = rejection_reason
            attempts.append(attempt_meta)
            plan["trusted_source_failure_class"] = "candidate_rejected"
            plan["trusted_source_rejection_reason"] = rejection_reason
            plan["provider_blocker"] = f"support source plan rejected: {rejection_reason}"
            requested_ids = list(source_query_generation.get("source_query_requested_row_ids", []) or [])
            repair_note = (
                rejection_reason
                + (
                    "; generate target-matched source_candidates for requested rows: "
                    + ", ".join(str(item) for item in requested_ids[:8])
                    if requested_ids
                    else ""
                )
            )
            if attempt_number < TRUSTED_SOURCE_TRIAGE_MAX_ATTEMPTS:
                continue
            break
        attempt_meta["accepted"] = True
        attempts.append(attempt_meta)
        plan.update(validated)
        plan["status"] = "completed"
        plan["provider_blocker"] = ""
        plan["trusted_source_failure_class"] = ""
        plan["trusted_source_rejection_reason"] = ""
        break
    plan["trusted_source_attempts"] = attempts
    plan["trusted_source_attempt_count"] = len(attempts)
    plan["source_plan_id"] = _record_id("source-plan", plan)
    record = _append_ledger(operator_root, "directive_support_source_plans", plan)
    _write_json(autonomy_root(operator_root) / "directive_support_source_plan_latest.json", record)
    return record


def _validate_trusted_source_triage_structured(
    structured: Mapping[str, Any],
) -> tuple[dict[str, Any], str]:
    citation_summaries = []
    for item in list(structured.get("citation_summaries", []) or [])[:8]:
        row = dict(item) if isinstance(item, Mapping) else {}
        source_hint = _truncate(str(row.get("source_hint", "")).strip(), 160)
        claim = _truncate(str(row.get("claim", "")).strip(), 280)
        relevance = _truncate(str(row.get("relevance", "")).strip(), 240)
        if source_hint and claim and relevance:
            citation_summaries.append(
                {
                    "source_hint": source_hint,
                    "claim": claim,
                    "relevance": relevance,
                }
            )
    if not citation_summaries:
        return {}, "missing_citation_summaries"

    action_suggestions = _bounded_string_list(structured.get("action_suggestions", []))
    if not action_suggestions:
        return {}, "missing_bounded_action_suggestions"
    unsafe_suggestions = [
        item for item in action_suggestions if not _trusted_source_triage_action_is_bounded(item)
    ]
    if unsafe_suggestions:
        return {}, "unsafe_action_suggestion"

    return {
        "citation_summaries": citation_summaries,
        "citation_count": len(citation_summaries),
        "relevance_tags": _bounded_string_list(structured.get("relevance_tags", []), item_limit=80),
        "novelty_tags": _bounded_string_list(structured.get("novelty_tags", []), item_limit=80),
        "action_suggestions": action_suggestions,
        "rejected_claims": _bounded_string_list(structured.get("rejected_claims", [])),
        "weak_claims": _bounded_string_list(structured.get("weak_claims", [])),
    }, ""


def _validate_role_specific_research_adapter(adapter: Mapping[str, Any]) -> tuple[bool, str]:
    citation_summaries = [
        dict(item)
        for item in list(adapter.get("citation_summaries", []) or [])
        if isinstance(item, Mapping)
        and str(item.get("source_hint", "") or "").strip()
        and str(item.get("claim", "") or "").strip()
        and str(item.get("relevance", "") or "").strip()
    ]
    if not citation_summaries:
        return False, "missing_citation_summaries"
    actions = _bounded_string_list(adapter.get("bounded_action_suggestions", []))
    if not actions:
        return False, "missing_bounded_action_suggestions"
    if any(not _trusted_source_triage_action_is_bounded(item) for item in actions):
        return False, "unsafe_action_suggestion"
    required_fields = (
        "directive_context",
        "required_evidence_types",
        "success_metric_template",
        "validation_requirements",
    )
    for field in required_fields:
        value = adapter.get(field)
        if isinstance(value, Mapping) and value:
            continue
        if isinstance(value, list) and value:
            continue
        if isinstance(value, str) and value.strip():
            continue
        return False, f"missing_{field}"
    return True, ""


def _role_specific_research_adapter(
    operator_root: str | Path,
    *,
    operation: Mapping[str, Any],
    role_profile: Mapping[str, Any],
    trusted_digest: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    digest = dict(trusted_digest or {})
    citation_summaries = [
        dict(item)
        for item in list(digest.get("citation_summaries", []) or [])
        if isinstance(item, Mapping)
    ]
    if not citation_summaries:
        missing_skills = [
            str(item)
            for item in list(role_profile.get("missing_skills", []) or [])[:3]
            if str(item).strip()
        ]
        citation_summaries = [
            {
                "source_hint": "role_profile",
                "claim": "Local role profile identifies role-specific research pressure: "
                + _truncate("; ".join(missing_skills), 220),
                "relevance": "Provides bounded local context for directive-specific research adapter planning.",
            }
        ]
    required_evidence_types = [
        str(item)
        for item in list(role_profile.get("trusted_knowledge_gaps", []) or [])[:6]
        if str(item).strip()
    ]
    if not required_evidence_types:
        required_evidence_types = [
            str(item)
            for item in list(role_profile.get("missing_skills", []) or [])[:4]
            if str(item).strip()
        ]
    action_suggestions = _bounded_string_list(digest.get("action_suggestions", []))
    if not action_suggestions:
        topic = (
            str(role_profile.get("next_learning_pressure", "") or "").strip()
            or str(role_profile.get("inferred_mission_domain", "") or "").strip()
            or "directive prototype evidence"
        )
        action_suggestions = [
            "Create a Novali-owned evidence map for "
            + _truncate(topic, 120)
            + " with directive-specific acceptance gates."
        ]
    adapter: dict[str, Any] = {
        "schema_name": "RoleSpecificResearchAdapter",
        "schema_version": AUTONOMY_SCHEMA_VERSION,
        "created_at": _now(),
        "role_specific_research_adapter_id": "",
        "operation_id": str(operation.get("operation_id", "")),
        "status": "blocked",
        "role_profile_id": str(role_profile.get("role_profile_id", "")),
        "trusted_source_triage_digest_id": str(digest.get("trusted_source_triage_digest_id", "") or ""),
        "directive_context": {
            "mission_domain": str(role_profile.get("inferred_mission_domain", "") or ""),
            "next_learning_pressure": str(role_profile.get("next_learning_pressure", "") or ""),
            "missing_skills": list(role_profile.get("missing_skills", []) or [])[:8],
            "operation_action": str(operation.get("action", "") or ""),
            "directive_id": str(operation.get("directive_id", "") or ""),
            "directive_title": str(operation.get("directive_title", "") or operation.get("title", "") or ""),
        },
        "required_evidence_types": required_evidence_types,
        "success_metric_template": {
            "metric": "directive_specific_success_metric",
            "threshold": "named evidence refs, validation fixtures, expected files, acceptance tests, and go/no-go gates are present",
            "failure_signal": "generic role research that cannot change a prototype handoff decision",
        },
        "validation_requirements": [
            "at least one cited or local role-profile evidence summary",
            "at least one bounded Novali-owned action suggestion",
            "no authority expansion, launch, restart, credential, or protected-root mutation",
        ],
        "bounded_action_suggestions": action_suggestions[:8],
        "citation_summaries": citation_summaries[:8],
        "citation_count": len(citation_summaries[:8]),
        "adapter_usable_for_learning": False,
        "validation_rejection_reason": "",
        "protected_root_write_allowed": False,
        "charter_mutated": False,
        "authority_boundary": "State-only research adapter; strict usefulness requires later consumption evidence.",
    }
    accepted, rejection_reason = _validate_role_specific_research_adapter(adapter)
    adapter["validation_rejection_reason"] = rejection_reason
    if accepted:
        adapter["status"] = "usable_learning_evidence"
        adapter["adapter_usable_for_learning"] = True
    adapter["role_specific_research_adapter_id"] = _record_id("role-research-adapter", adapter)
    record = _append_ledger(operator_root, "role_specific_research_adapters", adapter)
    _write_json(autonomy_root(operator_root) / "role_specific_research_adapter_latest.json", record)
    return record


def _role_specific_research_adapter_from_digest_if_needed(
    operator_root: str | Path,
    *,
    operation: Mapping[str, Any],
    digest: Mapping[str, Any],
) -> dict[str, Any]:
    if not bool(digest.get("digest_usable_for_learning", False)):
        return {}
    role_profile = _latest(operator_root, "role_specialization_profiles")
    missing_skills = {
        str(item).strip().lower()
        for item in list(role_profile.get("missing_skills", []) or [])
        if str(item).strip()
    }
    if "role-specific research adapter" not in missing_skills:
        return {}
    digest_id = str(digest.get("trusted_source_triage_digest_id", "") or "")
    latest_adapter = _latest(operator_root, "role_specific_research_adapters")
    if digest_id and str(latest_adapter.get("trusted_source_triage_digest_id", "") or "") == digest_id:
        return latest_adapter
    return _role_specific_research_adapter(
        operator_root,
        operation=operation,
        role_profile=role_profile,
        trusted_digest=digest,
    )


def _trusted_source_workflow_profile_metadata(
    source: Mapping[str, Any] | None = None,
) -> dict[str, str]:
    payload = dict(source or {})
    return {
        "trusted_source_workflow_profile": str(
            payload.get("trusted_source_workflow_profile", "")
            or TRUSTED_SOURCE_WORKFLOW_PROFILE_ID
        ),
        "platform_prompt_id": str(
            payload.get("platform_prompt_id", "") or TRUSTED_SOURCE_PLATFORM_PROMPT_ID
        ),
        "platform_prompt_version": str(
            payload.get("platform_prompt_version", "")
            or TRUSTED_SOURCE_PLATFORM_PROMPT_VERSION
        ),
        "profile_source": str(payload.get("profile_source", "") or TRUSTED_SOURCE_PROFILE_SOURCE),
    }


def _trusted_source_profiled_input(task_prompt: str) -> str:
    return (
        TRUSTED_SOURCE_RESEARCH_HEAVY_PROFILE_PROMPT
        + "\n\nNovali trusted-source task contract:\n"
        + str(task_prompt or "").strip()
    ).strip()


def _trusted_source_triage_payload(
    *,
    model: str,
    context: Mapping[str, Any],
    repair_note: str = "",
) -> dict[str, Any]:
    prompt = (
        "Create a compact trusted-source literature triage digest for Novali. "
        "Return JSON only. Use web search when available, source hints, and redacted context; clearly "
        "separate retrieved source evidence from hinted or inferred evidence. Keep suggestions bounded "
        "to Novali-owned state capabilities. "
        "Do not propose launching, approving, restarting, deleting, expanding authority, mutating protected roots, "
        "or handling raw secrets.\n"
        + _truncate(_json_dump(_redact_autonomy_value(dict(context))), 5000)
    )
    if repair_note:
        prompt += (
            "\n\nPrevious attempt failed validation: "
            + repair_note
            + ". Repair the response with at least one cited summary and one bounded Novali-owned action suggestion. "
            "Return only valid JSON matching the schema."
        )
    return {
        "model": str(model or TRUSTED_SOURCE_EXTERNAL_MODEL_PREFERENCE[0]),
        "store": False,
        "input": _trusted_source_profiled_input(prompt),
        "tools": [{"type": "web_search"}],
        "metadata": _trusted_source_workflow_profile_metadata(),
        "max_output_tokens": 700,
        "text": {
            "format": {
                "type": "json_schema",
                "name": "novali_trusted_source_literature_triage_digest",
                "strict": True,
                "schema": _trusted_source_triage_schema(),
            }
        },
    }


def _directive_build_grade_support_payload(
    *,
    model: str,
    context: Mapping[str, Any],
    repair_note: str = "",
) -> dict[str, Any]:
    prompt = (
        "Create a directive-specific build-grade support digest for Novali child containers. "
        "Return JSON only. The output must contain child_support_rows that directly cover the current "
        "target artifact and missing fields with concrete source-backed engineering values. "
        "Do not return generic autonomy summaries, literature-triage commentary, or placeholder values. "
        "Children are network-denied, credential-free, and review-only, so every usable row needs a "
        "source_url or concrete citation_ref plus an evidence_ref. Set grants_execution_authority to false "
        "on every row.\n\n"
        "For Full Dive directives, support both non-invasive hardware and software interface design: "
        "interface architecture, signal chain, electronics BOM, electrical interface spec, bench fixture, "
        "HAL/software hooks, sampling and latency budgets, BOM quantity, measurable specs, substitution policy, "
        "test equipment, risk-if-missing, safety/risk controls, go/no-go traces, research evidence, and regulatory "
        "assumptions. Block human-subject, invasive, clinical, or unsafe stimulation claims.\n\n"
        "For Magnetic Forge directives, prioritize BOM and sensor-array split rows with manufacturer, MPN, "
        "datasheet/source URL, ratings, quantity, cost basis, fixture links, risk links, standards assumptions, and "
        "go/no-go traces. When context includes support_role_lane_required_roles, emit at least one "
        "child_support_row for each required lane, set target_role to the exact lane, and do not collapse "
        "those lanes into one aggregate sensor_array row.\n\n"
        "When provider_field_lane_request.requested_rows is present, every accepted child_support_row "
        "must set requested_row_id to exactly one requested row, target the exact requested artifact/role, "
        "and cover every requested required_field for that requested row. Retry only the rejected or "
        "uncovered requested rows when validator feedback is provided.\n\n"
        "Context JSON follows:\n"
        + _truncate(_json_dump(_redact_autonomy_value(dict(context))), 9000)
    )
    if repair_note:
        prompt += (
            "\n\nPrevious attempt failed validation: "
            + _truncate(repair_note, 500)
            + ". Repair with target-matched, field-covering child_support_rows only."
        )
    return {
        "model": str(model or TRUSTED_SOURCE_EXTERNAL_MODEL_PREFERENCE[0]),
        "store": False,
        "input": _trusted_source_profiled_input(prompt),
        "tools": [{"type": "web_search"}],
        "metadata": _trusted_source_workflow_profile_metadata(),
        "max_output_tokens": 2200,
        "text": {
            "format": {
                "type": "json_schema",
                "name": "novali_directive_build_grade_support_digest",
                "strict": True,
                "schema": _directive_build_grade_support_schema(),
            }
        },
    }


def _seed_row_field_set(row: Mapping[str, Any]) -> set[str]:
    from .support_evidence import normalize_support_field_name

    fields = {
        normalize_support_field_name(item)
        for item in list(row.get("covered_fields", []) or row.get("required_fields", []) or [])
        if normalize_support_field_name(item)
    }
    spec_values = row.get("spec_values") or row.get("concrete_spec_values") or {}
    if isinstance(spec_values, Mapping):
        for key, value in spec_values.items():
            if str(value or "").strip():
                normalized = normalize_support_field_name(key)
                if normalized:
                    fields.add(normalized)
    elif isinstance(spec_values, (list, tuple, set)):
        for item in spec_values:
            text = str(item or "")
            if "=" in text:
                key, value = text.split("=", 1)
            elif ":" in text:
                key, value = text.split(":", 1)
            else:
                continue
            if str(value or "").strip():
                normalized = normalize_support_field_name(key)
                if normalized:
                    fields.add(normalized)
    for key, value in row.items():
        if str(value or "").strip():
            normalized = normalize_support_field_name(key)
            if normalized:
                fields.add(normalized)
    if str(row.get("source_url", "") or row.get("url", "") or row.get("citation_ref", "") or "").strip():
        fields.add("datasheet_url")
    return fields


_CANONICAL_SUPPORT_ROLE_LANES = {
    "thermal_sensor_interface",
    "current_sensor_interface",
    "magnetic_field_sensor_or_gaussmeter",
    "coolant_flow_or_temperature_sensor",
    "daq_logger_or_microcontroller_interface",
}


def _seed_row_identity_tokens(*values: Any) -> set[str]:
    tokens: set[str] = set()
    stop_words = {
        "bom",
        "bill",
        "materials",
        "json",
        "row",
        "lane",
        "component",
        "support",
        "source",
        "backed",
        "evidence",
        "full",
        "dive",
    }
    for value in values:
        text = str(value or "").lower()
        for token in re.split(r"[^a-z0-9]+", text):
            if len(token) < 4 or token in stop_words:
                continue
            tokens.add(token)
    return tokens


def _seed_row_identity_matches_requested(
    seed_row: Mapping[str, Any],
    requested_row: Mapping[str, Any],
) -> bool:
    requested_tokens = _seed_row_identity_tokens(
        requested_row.get("requested_row_id", ""),
        requested_row.get("target_row_id", ""),
        requested_row.get("design_artifact_row_id", ""),
        requested_row.get("source_query_hint", ""),
    )
    seed_tokens = _seed_row_identity_tokens(
        seed_row.get("row_id", ""),
        seed_row.get("support_row_id", ""),
        seed_row.get("seed_template_id", ""),
        seed_row.get("target_row_id", ""),
        seed_row.get("design_artifact_row_id", ""),
        seed_row.get("claim", ""),
        seed_row.get("source_query_hint", ""),
    )
    if not requested_tokens or not seed_tokens:
        return False
    return bool(requested_tokens & seed_tokens)


def _seed_row_matches_requested_row(
    seed_row: Mapping[str, Any],
    requested_row: Mapping[str, Any],
    *,
    target_artifact: str,
) -> bool:
    from .support_evidence import normalize_support_field_name, normalize_support_role_lane

    def _template_row_id(value: Any) -> str:
        text = str(value or "").strip()
        if text.lower() in {
            "",
            "[redacted]",
            "redacted",
            "[placeholder]",
            "placeholder",
            "artifact_field_gap",
            "unknown",
            "n/a",
            "na",
        }:
            return ""
        return text

    seed_target = str(seed_row.get("target_artifact", "") or seed_row.get("artifact", "") or "").strip()
    requested_target = str(requested_row.get("target_artifact", "") or target_artifact or "").strip()
    if requested_target and seed_target and seed_target != requested_target:
        return False
    seed_requested_id = str(seed_row.get("requested_row_id", "") or "").strip()
    requested_id = str(requested_row.get("requested_row_id", "") or "").strip()
    if seed_requested_id and requested_id and seed_requested_id != requested_id:
        return False
    requested_role = normalize_support_role_lane(requested_row.get("target_role") or requested_row.get("role"))
    seed_role = normalize_support_role_lane(seed_row.get("target_role") or seed_row.get("role") or seed_row.get("required_for"))
    requested_role_is_lane = requested_role in _CANONICAL_SUPPORT_ROLE_LANES
    seed_role_is_lane = seed_role in _CANONICAL_SUPPORT_ROLE_LANES
    if requested_role_is_lane != seed_role_is_lane:
        return False
    if requested_role_is_lane and seed_role_is_lane and requested_role != seed_role:
        return False
    requested_target_row = _template_row_id(
        requested_row.get("target_row_id", "")
        or requested_row.get("design_artifact_row_id", "")
        or ""
    )
    seed_target_row = _template_row_id(
        seed_row.get("target_row_id", "")
        or seed_row.get("design_artifact_row_id", "")
        or seed_row.get("seed_target_row_id", "")
        or ""
    )
    if requested_target_row and seed_target_row and requested_target_row != seed_target_row:
        return False
    if (
        not requested_role_is_lane
        and not seed_role_is_lane
        and requested_target_row
        and not seed_target_row
        and not _seed_row_identity_matches_requested(seed_row, requested_row)
    ):
        return False
    required_fields = {
        normalize_support_field_name(item)
        for item in list(requested_row.get("required_fields", []) or [])
        if normalize_support_field_name(item)
    }
    if required_fields and not required_fields.issubset(_seed_row_field_set(seed_row)):
        return False
    return True


def _seed_pack_rows_for_build_grade_request(
    operator_root: str | Path,
    *,
    context: Mapping[str, Any],
    provider_field_lane_request: Mapping[str, Any],
) -> dict[str, Any]:
    seed_dir = Path(operator_root) / "conveyor" / "operator_support_seed_packs"
    if not seed_dir.exists():
        return {}
    target_artifact = str(
        provider_field_lane_request.get("target_artifact", "")
        or context.get("target_artifact", "")
        or ""
    ).strip()
    directive_family = str(context.get("directive_family", "") or "").strip()
    requested_rows = [
        dict(row)
        for row in list(provider_field_lane_request.get("requested_rows", []) or [])
        if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
    ]
    if not requested_rows:
        return {}
    bound_rows: list[dict[str, Any]] = []
    bound_requested_ids: set[str] = set()
    used_seed_row_keys: set[tuple[str, int]] = set()
    used_seed_pack_ids: list[str] = []
    used_seed_pack_paths: list[str] = []
    for path in sorted(seed_dir.glob("*.json")):
        payload = _read_json(path)
        if str(payload.get("schema_name", "") or "") != "OperatorApprovedSupportSeedPack":
            continue
        if bool(payload.get("grants_execution_authority", False)):
            continue
        seed_target = str(payload.get("target_artifact", "") or "").strip()
        if target_artifact and seed_target and seed_target != target_artifact:
            continue
        seed_family = str(payload.get("directive_family", "") or "").strip()
        if directive_family and seed_family and seed_family != directive_family:
            continue
        seed_rows: list[dict[str, Any]] = []
        for key in (
            "child_support_rows",
            "support_row_templates",
            "child_support_row_templates",
            "requested_row_templates",
            "row_templates",
        ):
            seed_rows.extend(
                dict(row)
                for row in list(payload.get(key, []) or [])
                if isinstance(row, Mapping)
            )
        if not seed_rows:
            continue
        pack_id = str(payload.get("operator_seed_pack_id", "") or payload.get("seed_pack_id", "") or path.stem)
        pack_used = False
        for requested in requested_rows:
            requested_id = str(requested.get("requested_row_id", "") or "").strip()
            if not requested_id or requested_id in bound_requested_ids:
                continue
            selected_index = -1
            selected_row: dict[str, Any] = {}
            for index, row in enumerate(seed_rows):
                if (str(path), index) in used_seed_row_keys:
                    continue
                if _seed_row_matches_requested_row(
                    row,
                    requested,
                    target_artifact=target_artifact,
                ):
                    selected_index = index
                    selected_row = row
                    break
            if selected_index < 0:
                continue
            used_seed_row_keys.add((str(path), selected_index))
            target_row_id = str(
                requested.get("target_row_id", "")
                or requested.get("design_artifact_row_id", "")
                or selected_row.get("target_row_id", "")
                or selected_row.get("design_artifact_row_id", "")
                or requested_id
            ).strip()
            row = dict(selected_row)
            row["requested_row_id"] = requested_id
            row["target_artifact"] = str(requested.get("target_artifact", "") or target_artifact or row.get("target_artifact", "") or "")
            row["target_row_id"] = target_row_id
            if str(requested.get("target_role", "") or "").strip():
                row["target_role"] = str(requested.get("target_role", "") or "").strip()
            row["operator_seed_pack_id"] = pack_id
            row["operator_seed_pack_template_bound"] = True
            row["grants_execution_authority"] = False
            bound_rows.append(row)
            bound_requested_ids.add(requested_id)
            pack_used = True
        if pack_used:
            used_seed_pack_ids.append(pack_id)
            used_seed_pack_paths.append(str(path))
        requested_id_set = {
            str(row.get("requested_row_id", "") or "").strip()
            for row in requested_rows
            if str(row.get("requested_row_id", "") or "").strip()
        }
        if requested_id_set and requested_id_set.issubset(bound_requested_ids):
            break
    if not bound_rows:
        return {}
    validated, rejection_reason = _validate_directive_build_grade_support_structured(
        {"child_support_rows": bound_rows},
        context={
            **dict(context),
            "provider_field_lane_request": provider_field_lane_request,
            "provider_field_lane_request_id": str(
                provider_field_lane_request.get("provider_field_lane_request_id", "") or ""
            ),
        },
    )
    if rejection_reason and not list(validated.get("child_support_rows", []) or []):
        return {}
    if rejection_reason and not list(validated.get("accepted_requested_row_ids", []) or []):
        return {}
    seed_pack_ids = list(dict.fromkeys(used_seed_pack_ids))
    seed_pack_paths = list(dict.fromkeys(used_seed_pack_paths))
    seed_id = seed_pack_ids[0] if len(seed_pack_ids) == 1 else _record_id("operator-seed-pack-set", seed_pack_ids)
    uncovered_ids = list(validated.get("uncovered_requested_row_ids", []) or [])
    result = {
        "operator_seed_pack_id": seed_id,
        "operator_seed_pack_ids": seed_pack_ids,
        "operator_seed_pack_path": seed_pack_paths[0] if len(seed_pack_paths) == 1 else "",
        "operator_seed_pack_paths": seed_pack_paths,
        "validated": validated,
        "grants_execution_authority": False,
    }
    if rejection_reason or uncovered_ids:
        result["seed_pack_partial_acquisition"] = True
        result["seed_pack_rejection_reason"] = rejection_reason or "uncovered_requested_rows"
    return result


def _operator_seed_pack_policy(context: Mapping[str, Any]) -> str:
    policy = str(
        context.get("operator_seed_pack_policy", "")
        or os.environ.get("NOVALI_OPERATOR_SEED_PACK_POLICY", "")
        or ""
    ).strip()
    if policy == "disabled_by_operator_experiment":
        return policy
    return "enabled"


def _seed_source_plan_from_rows(
    *,
    context: Mapping[str, Any],
    provider_field_lane_request: Mapping[str, Any],
    seed_pack_id: str,
    rows: Iterable[Mapping[str, Any]],
) -> dict[str, Any]:
    query_generation = _requested_row_source_queries(
        context,
        provider_field_lane_request,
        reason="operator_seed_pack_source_rows",
    )
    source_candidates: list[dict[str, Any]] = []
    for index, row in enumerate(rows, start=1):
        source_url = str(row.get("source_url", "") or row.get("url", "") or "").strip()
        citation_ref = str(row.get("citation_ref", "") or "").strip()
        candidate_id = str(row.get("source_candidate_id", "") or "").strip() or _record_id(
            "seed-source",
            {
                "operator_seed_pack_id": seed_pack_id,
                "requested_row_id": str(row.get("requested_row_id", "") or ""),
                "source_ref": source_url or citation_ref,
                "index": index,
            },
        )
        source_candidates.append(
            {
                "source_candidate_id": candidate_id,
                "target_artifact": str(row.get("target_artifact", "") or context.get("target_artifact", "") or ""),
                "target_role": str(row.get("target_role", "") or ""),
                "covered_fields": list(row.get("covered_fields", []) or row.get("required_fields", []) or []),
                "title": str(row.get("title", "") or row.get("claim", "") or candidate_id)[:160],
                "source_url": source_url,
                "citation_ref": citation_ref,
                "relevance": str(row.get("relevance", "") or "Operator-approved seed row bound to current requested support row.")[:280],
                "operator_seed_pack_id": seed_pack_id,
                "grants_execution_authority": False,
            }
        )
    source_plan = {
        "schema_name": "DirectiveSupportSourcePlan",
        "schema_version": AUTONOMY_SCHEMA_VERSION,
        "created_at": _now(),
        "source_plan_id": "",
        "status": "completed",
        "support_request_id": str(context.get("support_request_id", "") or ""),
        "directive_id": str(context.get("directive_id", "") or ""),
        "target_artifact": str(context.get("target_artifact", "") or ""),
        "required_fields": _bounded_string_list(context.get("missing_fields", []), limit=24, item_limit=80),
        "search_queries": list(query_generation.get("generated_search_queries", []) or []),
        "source_candidates": source_candidates,
        "source_candidate_count": len(source_candidates),
        "rejected_source_types": [],
        "relevance_tags": ["operator_seed_pack"],
        "operator_seed_pack_used": True,
        "operator_seed_pack_id": seed_pack_id,
        "abstract_lane_decomposition_state": str(
            provider_field_lane_request.get("abstract_lane_decomposition_state", "") or ""
        ),
        "abstract_lane_decomposition_reason": str(
            provider_field_lane_request.get("abstract_lane_decomposition_reason", "") or ""
        ),
        "abstract_source_requested_row_ids": list(
            provider_field_lane_request.get("abstract_source_requested_row_ids", []) or []
        ),
        "decomposed_requested_row_ids": list(
            provider_field_lane_request.get("decomposed_requested_row_ids", []) or []
        ),
        "grants_execution_authority": False,
        **query_generation,
        **_trusted_source_workflow_profile_metadata(),
    }
    source_plan["source_plan_id"] = _record_id("source-plan", source_plan)
    return source_plan


def _requested_row_evidence_questions(
    context: Mapping[str, Any],
    provider_field_lane_request: Mapping[str, Any],
) -> list[dict[str, Any]]:
    target_artifact = str(
        provider_field_lane_request.get("target_artifact", "")
        or context.get("target_artifact", "")
        or ""
    ).strip()
    questions: list[dict[str, Any]] = []
    for row in list(provider_field_lane_request.get("requested_rows", []) or []):
        if not isinstance(row, Mapping):
            continue
        requested_row_id = str(row.get("requested_row_id", "") or "").strip()
        if not requested_row_id:
            continue
        required_fields = _bounded_string_list(
            row.get("required_fields", []) or context.get("missing_fields", []),
            limit=24,
            item_limit=80,
        )
        question = {
            "question_id": _record_id(
                "evidence-question",
                {
                    "support_request_id": str(context.get("support_request_id", "") or ""),
                    "requested_row_id": requested_row_id,
                    "target_artifact": str(row.get("target_artifact", "") or target_artifact),
                },
            ),
            "requested_row_id": requested_row_id,
            "target_artifact": str(row.get("target_artifact", "") or target_artifact),
            "target_row_id": str(
                row.get("target_row_id", "")
                or row.get("design_artifact_row_id", "")
                or ""
            ),
            "target_role": str(row.get("target_role", "") or ""),
            "required_fields": required_fields,
            "acceptable_source_types": [
                "operator_seed_pack",
                "local_trusted_source_mount",
                "direct_url_fetch",
                "free_open_source_adapter",
                "manufacturer_datasheet",
                "official_manual_or_specification",
                "standards_or_regulatory_document",
            ],
            "rejection_examples": [
                "missing_requested_row_id",
                "wrong_target_artifact",
                "placeholder_value",
                "citation_only_summary",
                "missing_concrete_field_value",
                "grants_execution_authority",
            ],
            "expected_support_row_shape": {
                "requested_row_id": requested_row_id,
                "target_artifact": str(row.get("target_artifact", "") or target_artifact),
                "target_role": str(row.get("target_role", "") or ""),
                "required_fields": required_fields,
                "spec_values": "concrete field=value entries",
                "source_url_or_citation": "required",
                "evidence_ref": "required",
                "grants_execution_authority": False,
            },
            "source_query_hint": str(row.get("source_query_hint", "") or ""),
            "grants_execution_authority": False,
        }
        questions.append(question)
    return questions[:24]


def _retrieved_knowledge_ref_from_row(
    row: Mapping[str, Any],
    *,
    source_kind: str,
    retrieved_at: str,
) -> dict[str, Any]:
    source_ref = str(
        row.get("source_url", "")
        or row.get("url", "")
        or row.get("citation_ref", "")
        or row.get("path", "")
        or row.get("source_ref", "")
        or ""
    ).strip()
    return {
        "source_candidate_id": str(
            row.get("source_candidate_id", "")
            or row.get("row_id", "")
            or row.get("support_row_id", "")
            or row.get("seed_template_id", "")
            or _record_id("knowledge-candidate", row)
        ),
        "requested_row_id": str(row.get("requested_row_id", "") or ""),
        "target_artifact": str(row.get("target_artifact", "") or row.get("artifact", "") or ""),
        "target_role": str(row.get("target_role", "") or row.get("role", "") or ""),
        "source_kind": source_kind,
        "source_ref": source_ref,
        "expected_mpn": str(row.get("expected_mpn", "") or ""),
        "expected_manufacturer": str(row.get("expected_manufacturer", "") or ""),
        "url": source_ref if source_ref.startswith(("http://", "https://")) else "",
        "path": source_ref if source_ref and not source_ref.startswith(("http://", "https://")) else "",
        "citation": str(row.get("citation_ref", "") or row.get("citation", "") or ""),
        "retrieved_at": retrieved_at,
        "license_usage_note": str(row.get("license_usage_note", "") or row.get("license", "") or "unknown"),
        "operator_seed_pack_id": str(row.get("operator_seed_pack_id", "") or ""),
        "grants_execution_authority": False,
    }


def _cheap_candidate_rows_from_context(context: Mapping[str, Any], key: str) -> list[dict[str, Any]]:
    rows: list[dict[str, Any]] = []
    for item in list(context.get(key, []) or []):
        if isinstance(item, Mapping):
            row = dict(item)
            row["grants_execution_authority"] = False
            rows.append(row)
    return rows[:20]


def _configured_knowledge_source_adapter_candidates(
    operator_root: str | Path,
    *,
    context: Mapping[str, Any],
    provider_field_lane_request: Mapping[str, Any],
) -> dict[str, list[dict[str, Any]]]:
    adapter_dir = Path(operator_root) / "conveyor" / "trusted_knowledge_source_adapters"
    if not adapter_dir.exists():
        return {}
    target_artifact = str(
        provider_field_lane_request.get("target_artifact", "")
        or context.get("target_artifact", "")
        or ""
    ).strip()
    requested_ids = {
        str(row.get("requested_row_id", "") or "").strip()
        for row in list(provider_field_lane_request.get("requested_rows", []) or [])
        if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
    }
    allowed_source_kinds = {
        "local_trusted_source_mount",
        "direct_url_fetch",
        "free_open_source_adapter",
        "mcp_free_source_adapter",
        "local_ollama_extraction",
    }
    rows_by_kind: dict[str, list[dict[str, Any]]] = {}
    for path in sorted(adapter_dir.glob("*.json")):
        payload = _read_json(path)
        if not payload or bool(payload.get("enabled", True)) is False:
            continue
        candidates: list[dict[str, Any]] = []
        for key in ("source_candidates", "retrieved_knowledge_candidates", "candidates"):
            candidates.extend(
                dict(row)
                for row in list(payload.get(key, []) or [])
                if isinstance(row, Mapping)
            )
        if not candidates and str(payload.get("source_candidate_id", "") or "").strip():
            candidates.append(dict(payload))
        for candidate in candidates:
            source_kind = str(
                candidate.get("source_kind", "")
                or payload.get("source_kind", "")
                or payload.get("adapter_kind", "")
                or ""
            ).strip()
            if source_kind not in allowed_source_kinds:
                continue
            candidate_requested_id = str(candidate.get("requested_row_id", "") or "").strip()
            if requested_ids and candidate_requested_id and candidate_requested_id not in requested_ids:
                continue
            if requested_ids and not candidate_requested_id:
                continue
            candidate_target = str(
                candidate.get("target_artifact", "")
                or payload.get("target_artifact", "")
                or ""
            ).strip()
            if target_artifact and candidate_target and candidate_target != target_artifact:
                continue
            row = dict(candidate)
            row["source_kind"] = source_kind
            row["target_artifact"] = candidate_target or target_artifact
            row["requested_row_id"] = candidate_requested_id
            row["configured_adapter_id"] = str(
                payload.get("adapter_id", "")
                or payload.get("registry_id", "")
                or path.stem
            )
            row["configured_adapter_path"] = str(path)
            row["grants_execution_authority"] = False
            rows_by_kind.setdefault(source_kind, []).append(row)
    return {key: value[:20] for key, value in rows_by_kind.items()}


def _trusted_knowledge_acquisition_route(
    operator_root: str | Path,
    *,
    context: Mapping[str, Any],
    provider_field_lane_request: Mapping[str, Any],
    seed_result: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    created_at = _now()
    operator_seed_pack_policy = _operator_seed_pack_policy(context)
    seed_packs_disabled = operator_seed_pack_policy == "disabled_by_operator_experiment"
    effective_seed_result: Mapping[str, Any] | None = None if seed_packs_disabled else seed_result
    requested_rows = [
        dict(row)
        for row in list(provider_field_lane_request.get("requested_rows", []) or [])
        if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
    ]
    requested_ids = [
        str(row.get("requested_row_id", "") or "").strip()
        for row in requested_rows
        if str(row.get("requested_row_id", "") or "").strip()
    ]
    requested_id_set = set(requested_ids)
    validated = dict((effective_seed_result or {}).get("validated", {}) or {})
    raw_accepted_ids = (
        validated.get("accepted_requested_row_ids")
        if "accepted_requested_row_ids" in validated
        else provider_field_lane_request.get("accepted_requested_row_ids", [])
    )
    raw_uncovered_ids = (
        validated.get("uncovered_requested_row_ids")
        if "uncovered_requested_row_ids" in validated
        else provider_field_lane_request.get("uncovered_requested_row_ids", [])
    )
    accepted_ids = [
        str(item or "").strip()
        for item in list(raw_accepted_ids or [])
        if str(item or "").strip()
        and (not requested_id_set or str(item or "").strip() in requested_id_set)
    ]
    uncovered_ids = [
        str(item or "").strip()
        for item in list(raw_uncovered_ids or [])
        if str(item or "").strip()
        and (not requested_id_set or str(item or "").strip() in requested_id_set)
    ]
    if requested_ids and not uncovered_ids:
        uncovered_ids = [requested_id for requested_id in requested_ids if requested_id not in set(accepted_ids)]
    seed_rows = [
        dict(row)
        for row in list(validated.get("child_support_rows", []) or [])
        if isinstance(row, Mapping)
        and (
            not requested_id_set
            or str(row.get("requested_row_id", "") or "").strip() in requested_id_set
        )
    ]
    seed_row_bound_ids = {
        str(row.get("requested_row_id", "") or "").strip()
        for row in seed_rows
        if str(row.get("requested_row_id", "") or "").strip()
    }
    seed_accepted_without_rows = [
        requested_id
        for requested_id in accepted_ids
        if requested_id not in seed_row_bound_ids
    ]
    if seed_accepted_without_rows:
        accepted_ids = [
            requested_id
            for requested_id in accepted_ids
            if requested_id in seed_row_bound_ids
        ]
        uncovered_ids = list(
            dict.fromkeys(
                list(uncovered_ids)
                + seed_accepted_without_rows
                + [
                    requested_id
                    for requested_id in requested_ids
                    if requested_id not in set(accepted_ids)
                    and requested_id not in set(uncovered_ids)
                ]
            )
        )
    seed_state = "unavailable"
    seed_dir = Path(operator_root) / "conveyor" / "operator_support_seed_packs"
    if seed_packs_disabled:
        seed_state = "disabled_by_operator_experiment"
        accepted_ids = [
            str(item or "").strip()
            for item in list(provider_field_lane_request.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
            and (not requested_id_set or str(item or "").strip() in requested_id_set)
        ]
        backing_rows: list[dict[str, Any]] = []
        for row_source in (context, provider_field_lane_request):
            for row_key in (
                "child_support_rows",
                "accepted_field_lane_rows",
                "support_role_lane_accepted_rows",
                "support_rows",
            ):
                backing_rows.extend(
                    dict(row)
                    for row in list(row_source.get(row_key, []) or [])
                    if isinstance(row, Mapping)
                )
        backing_requested_ids = {
            str(row.get("requested_row_id", "") or "").strip()
            for row in backing_rows
            if str(row.get("requested_row_id", "") or "").strip()
            and not bool(row.get("grants_execution_authority", False))
            and (
                str(row.get("evidence_ref", "") or "").strip()
                or str(row.get("source_url", "") or "").strip()
                or str(row.get("citation_ref", "") or "").strip()
                or str(row.get("design_reduction_provenance", "") or "").strip()
            )
        }
        accepted_ids = [
            requested_id
            for requested_id in accepted_ids
            if requested_id in backing_requested_ids
        ]
        uncovered_ids = [
            str(item or "").strip()
            for item in list(provider_field_lane_request.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip()
            and (not requested_id_set or str(item or "").strip() in requested_id_set)
        ]
        if requested_ids:
            accepted_set = set(accepted_ids)
            uncovered_ids = list(
                dict.fromkeys(
                    uncovered_ids
                    + [
                        requested_id
                        for requested_id in requested_ids
                        if requested_id not in accepted_set
                    ]
                )
            )
        seed_rows = []
        seed_accepted_without_rows = []
    elif effective_seed_result:
        seed_state = "accepted" if accepted_ids and not uncovered_ids else "partial"
    elif seed_dir.exists():
        seed_state = "miss"
    cheap_source_attempts: list[dict[str, Any]] = [
        {
            "source_kind": "operator_seed_cache",
            "attempt_state": seed_state,
            "accepted_requested_row_ids": accepted_ids,
            "uncovered_requested_row_ids": uncovered_ids,
            "candidate_count": len(seed_rows),
            "operator_seed_pack_id": str((effective_seed_result or {}).get("operator_seed_pack_id", "") or ""),
            "operator_seed_pack_policy": operator_seed_pack_policy,
            "accepted_without_bound_seed_row_rejected_ids": seed_accepted_without_rows,
            "grants_execution_authority": False,
        }
    ]
    retrieved_refs = [
        _retrieved_knowledge_ref_from_row(row, source_kind="operator_seed_cache", retrieved_at=created_at)
        for row in seed_rows
    ]
    context_candidate_sources = [
        ("local_trusted_source_mount", "local_trusted_source_candidates"),
        ("direct_url_fetch", "direct_url_source_candidates"),
        ("free_open_source_adapter", "free_source_candidates"),
        ("mcp_free_source_adapter", "mcp_source_candidates"),
        ("local_ollama_extraction", "local_ollama_extraction_candidates"),
    ]
    configured_candidates = _configured_knowledge_source_adapter_candidates(
        operator_root,
        context=context,
        provider_field_lane_request=provider_field_lane_request,
    )
    for source_kind, context_key in context_candidate_sources:
        candidate_rows = _cheap_candidate_rows_from_context(context, context_key)
        candidate_rows.extend(configured_candidates.get(source_kind, []) or [])
        candidate_rows = candidate_rows[:20]
        state = "candidate_normalized" if candidate_rows else "not_configured"
        cheap_source_attempts.append(
            {
                "source_kind": source_kind,
                "attempt_state": state,
                "candidate_count": len(candidate_rows),
                "accepted_requested_row_ids": [],
                "uncovered_requested_row_ids": uncovered_ids,
                "grants_execution_authority": False,
            }
        )
        retrieved_refs.extend(
            _retrieved_knowledge_ref_from_row(row, source_kind=source_kind, retrieved_at=created_at)
            for row in candidate_rows
        )
    non_seed_retrieved_count = len(
        [
            ref
            for ref in retrieved_refs
            if isinstance(ref, Mapping) and str(ref.get("source_kind", "") or "") != "operator_seed_cache"
        ]
    )
    cheap_source_rows_extracted_count = len(seed_rows) if not seed_packs_disabled else 0
    if accepted_ids and not uncovered_ids:
        cheap_source_retrieval_state = "accepted"
    elif accepted_ids or non_seed_retrieved_count:
        cheap_source_retrieval_state = "candidate_normalized"
    elif requested_ids:
        cheap_source_retrieval_state = "missing_source_candidates"
    else:
        cheap_source_retrieval_state = "no_requested_rows"
    openai_required = bool(uncovered_ids)
    route_order = [
        "operator_seed_cache",
        "local_trusted_source_mount",
        "direct_url_fetch",
        "free_open_source_adapter",
        "mcp_free_source_adapter",
        "local_ollama_extraction",
    ]
    if openai_required:
        route_order.append("openai_external_provider")
    evidence_questions = _requested_row_evidence_questions(context, provider_field_lane_request)
    route = {
        "schema_name": "TrustedKnowledgeAcquisitionRoute",
        "schema_version": AUTONOMY_SCHEMA_VERSION,
        "created_at": created_at,
        "trusted_knowledge_acquisition_route_id": "",
        "support_request_id": str(context.get("support_request_id", "") or ""),
        "current_provider_support_request_id": str(context.get("support_request_id", "") or ""),
        "directive_id": str(context.get("directive_id", "") or ""),
        "target_artifact": str(
            provider_field_lane_request.get("target_artifact", "")
            or context.get("target_artifact", "")
            or ""
        ),
        "provider_field_lane_request_id": str(
            provider_field_lane_request.get("provider_field_lane_request_id", "") or ""
        ),
        "operator_seed_pack_policy": operator_seed_pack_policy,
        "knowledge_acquisition_route": route_order,
        "cheap_source_attempts": cheap_source_attempts,
        "cheap_source_attempt_count": len(cheap_source_attempts),
        "cheap_source_retrieval_state": cheap_source_retrieval_state,
        "cheap_source_candidate_count": non_seed_retrieved_count,
        "cheap_source_rows_extracted_count": cheap_source_rows_extracted_count,
        "openai_escalation_avoided": not openai_required and bool(accepted_ids),
        "openai_escalation_required": openai_required,
        "openai_escalation_reason": (
            "uncovered_after_cheap_sources" if openai_required else "covered_by_cheap_sources"
        ),
        "retrieved_knowledge_refs": retrieved_refs[:40],
        "uncovered_after_cheap_sources": uncovered_ids,
        "accepted_requested_row_ids": accepted_ids,
        "accepted_without_bound_seed_row_rejected_ids": seed_accepted_without_rows,
        "evidence_questions": evidence_questions,
        "source_query_requested_row_ids": [
            str(item or "").strip()
            for item in list(provider_field_lane_request.get("uncovered_requested_row_ids", []) or uncovered_ids)
            if str(item or "").strip()
        ][:16],
        "grants_execution_authority": False,
    }
    route["trusted_knowledge_acquisition_route_id"] = _record_id(
        "knowledge-route",
        {
            "support_request_id": route["support_request_id"],
            "provider_field_lane_request_id": route["provider_field_lane_request_id"],
            "accepted_requested_row_ids": accepted_ids,
            "uncovered_after_cheap_sources": uncovered_ids,
        },
    )
    return route


def _source_candidate_plan_from_knowledge_route(
    *,
    context: Mapping[str, Any],
    provider_field_lane_request: Mapping[str, Any],
    route: Mapping[str, Any],
    reason: str,
) -> dict[str, Any]:
    query_generation = _requested_row_source_queries(
        context,
        provider_field_lane_request,
        reason=reason,
    )
    target_artifact = str(
        provider_field_lane_request.get("target_artifact", "")
        or context.get("target_artifact", "")
        or ""
    ).strip()
    requested_ids = {
        str(item or "").strip()
        for item in list(
            provider_field_lane_request.get("uncovered_requested_row_ids", [])
            or provider_field_lane_request.get("requested_row_ids", [])
            or []
        )
        if str(item or "").strip()
    }
    if not requested_ids:
        requested_ids = {
            str(row.get("requested_row_id", "") or "").strip()
            for row in list(provider_field_lane_request.get("requested_rows", []) or [])
            if isinstance(row, Mapping) and str(row.get("requested_row_id", "") or "").strip()
        }

    candidates: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str]] = set()
    for ref in list(route.get("retrieved_knowledge_refs", []) or []):
        if not isinstance(ref, Mapping) or bool(ref.get("grants_execution_authority", False)):
            continue
        requested_row_id = str(ref.get("requested_row_id", "") or "").strip()
        if requested_ids and requested_row_id and requested_row_id not in requested_ids:
            continue
        ref_target = str(ref.get("target_artifact", "") or "").strip()
        if target_artifact and ref_target and ref_target != target_artifact:
            continue
        source_ref = str(
            ref.get("url", "")
            or ref.get("source_ref", "")
            or ref.get("citation", "")
            or ref.get("path", "")
            or ""
        ).strip()
        if not source_ref:
            continue
        source_kind = str(ref.get("source_kind", "") or "retrieved_knowledge_candidate").strip()
        key = (requested_row_id, source_kind, source_ref)
        if key in seen:
            continue
        seen.add(key)
        candidates.append(
            {
                "schema_name": "RetrievedKnowledgeCandidate",
                "source_candidate_id": str(
                    ref.get("source_candidate_id", "")
                    or _record_id("source-candidate", requested_row_id, source_kind, source_ref)
                ),
                "requested_row_id": requested_row_id,
                "target_artifact": ref_target or target_artifact,
                "target_role": str(ref.get("target_role", "") or ""),
                "source_kind": source_kind,
                "source_url": str(ref.get("url", "") or (source_ref if source_ref.startswith(("http://", "https://")) else "")),
                "citation_ref": str(ref.get("citation", "") or source_ref),
                "source_ref": source_ref,
                "retrieval_timestamp": str(ref.get("retrieved_at", "") or _now()),
                "license_usage_note": str(ref.get("license_usage_note", "") or "unknown"),
                "candidate_acceptance_state": "requires_deterministic_field_validation",
                "expected_mpn": str(ref.get("expected_mpn", "") or ""),
                "expected_manufacturer": str(ref.get("expected_manufacturer", "") or ""),
                "relevance": "Cheap-source knowledge candidate bound to a current requested row; not accepted support evidence yet.",
                "grants_execution_authority": False,
            }
        )
    plan = {
        "schema_name": "DirectiveSupportSourcePlan",
        "schema_version": AUTONOMY_SCHEMA_VERSION,
        "created_at": _now(),
        "source_plan_id": "",
        "status": "blocked",
        "source_plan_state": "candidate_normalized_requires_deterministic_validation",
        "support_request_id": str(context.get("support_request_id", "") or ""),
        "current_provider_support_request_id": str(context.get("support_request_id", "") or ""),
        "provider_field_lane_request_id": str(
            provider_field_lane_request.get("provider_field_lane_request_id", "") or ""
        ),
        "directive_id": str(context.get("directive_id", "") or ""),
        "target_artifact": target_artifact,
        "required_fields": _bounded_string_list(context.get("missing_fields", []), limit=24, item_limit=80),
        "search_queries": list(query_generation.get("search_queries", []) or []),
        "generated_search_queries": list(query_generation.get("generated_search_queries", []) or []),
        "source_query_generation_state": str(query_generation.get("source_query_generation_state", "") or ""),
        "source_query_generation_reason": str(query_generation.get("source_query_generation_reason", "") or ""),
        "source_query_requested_row_ids": list(query_generation.get("source_query_requested_row_ids", []) or []),
        "source_candidates": candidates[:40],
        "source_candidate_count": len(candidates[:40]),
        "retrieved_knowledge_refs": list(route.get("retrieved_knowledge_refs", []) or [])[:40],
        "cheap_source_attempts": list(route.get("cheap_source_attempts", []) or [])[:12],
        "cheap_source_attempt_count": int(route.get("cheap_source_attempt_count", 0) or 0),
        "cheap_source_retrieval_state": str(route.get("cheap_source_retrieval_state", "") or ""),
        "cheap_source_candidate_count": int(route.get("cheap_source_candidate_count", 0) or 0),
        "cheap_source_rows_extracted_count": int(route.get("cheap_source_rows_extracted_count", 0) or 0),
        "operator_seed_pack_policy": str(route.get("operator_seed_pack_policy", "") or "enabled"),
        "uncovered_after_cheap_sources": list(route.get("uncovered_after_cheap_sources", []) or []),
        "trusted_source_rejection_reason": (
            "source_candidate_field_validation_required" if candidates else "missing_source_candidates"
        ),
        "provider_blocker": (
            "cheap source candidates require deterministic field extraction and requested-row validation"
            if candidates
            else "missing_source_candidates"
        ),
        "openai_escalation_required": bool(route.get("openai_escalation_required", False)),
        "openai_escalation_avoided": bool(route.get("openai_escalation_avoided", False))
        or bool(candidates),
        "grants_execution_authority": False,
        **_trusted_source_workflow_profile_metadata(),
    }
    plan["source_plan_id"] = _record_id("source-plan", plan)
    return plan


def _trusted_knowledge_retrieval_worker(
    operator_root: str | Path,
    *,
    context: Mapping[str, Any],
    provider_field_lane_request: Mapping[str, Any],
) -> dict[str, Any]:
    worker_context = {
        **dict(context),
        "operator_seed_pack_policy": "disabled_by_operator_experiment",
    }
    route = _trusted_knowledge_acquisition_route(
        operator_root,
        context=worker_context,
        provider_field_lane_request=provider_field_lane_request,
        seed_result={},
    )
    route = _append_ledger(operator_root, "trusted_knowledge_acquisition_routes", route)
    _write_json(
        autonomy_root(operator_root) / "trusted_knowledge_acquisition_route_latest.json",
        route,
    )
    source_plan = _source_candidate_plan_from_knowledge_route(
        context=worker_context,
        provider_field_lane_request=provider_field_lane_request,
        route=route,
        reason="trusted_knowledge_retrieval_worker",
    )
    from .source_evidence import read_cached_evidence, reuse_available_sources

    reuse_available_sources(Path(operator_root), list(source_plan.get("source_candidates", []) or []))
    extracted = read_cached_evidence(Path(operator_root), list(source_plan.get("source_candidates", []) or []))
    requested_by_id = {row.get("requested_row_id"): row for row in provider_field_lane_request.get("requested_rows", [])}
    for row in extracted["rows"]:
        contract = requested_by_id.get(row.get("requested_row_id"), {})
        row["target_role"] = str(contract.get("target_role", "") or contract.get("role", "") or "")
    validated: dict[str, Any] = {}
    validation_reason = ""
    if extracted["rows"]:
        validated, validation_reason = _validate_directive_build_grade_support_structured(
            {"target_artifact": source_plan.get("target_artifact", ""), "child_support_rows": extracted["rows"]},
            context={**worker_context, "source_plan": source_plan, "provider_field_lane_request": provider_field_lane_request},
        )
        accepted = list(validated.get("accepted_requested_row_ids", []) or [])
        route["accepted_requested_row_ids"] = list(dict.fromkeys(list(route.get("accepted_requested_row_ids", [])) + accepted))
        route["uncovered_after_cheap_sources"] = [row for row in route.get("uncovered_after_cheap_sources", []) if row not in accepted]
        route["cheap_source_rows_extracted_count"] = len(extracted["rows"])
        route["cheap_source_retrieval_state"] = "accepted" if not route["uncovered_after_cheap_sources"] else "partial_source_fields"
        route["openai_escalation_required"] = bool(route["uncovered_after_cheap_sources"])
        route["openai_escalation_avoided"] = not route["openai_escalation_required"]
        source_plan["source_plan_state"] = (
            "source_fields_extracted_contract_incomplete" if route["uncovered_after_cheap_sources"] else "validated_requested_rows"
        )
        source_plan["status"] = "blocked" if route["uncovered_after_cheap_sources"] else "completed"
        source_plan["provider_blocker"] = "incomplete_requested_row_fields" if route["uncovered_after_cheap_sources"] else ""
        source_plan["accepted_requested_row_ids"] = route["accepted_requested_row_ids"]
        source_plan["uncovered_requested_row_ids"] = route["uncovered_after_cheap_sources"]
        source_plan["source_rows_extracted_count"] = len(extracted["rows"])
        for candidate in source_plan.get("source_candidates", []):
            fact = next((row for row in extracted["rows"] if row["source_candidate_id"] == candidate["source_candidate_id"]), None)
            if fact:
                contract = requested_by_id.get(fact["requested_row_id"], {})
                candidate["candidate_acceptance_state"] = "source_fields_extracted"
                candidate["covered_fields"] = fact["covered_fields"]
                candidate["missing_required_fields"] = [field for field in contract.get("required_fields", []) if field not in fact["covered_fields"]]
                candidate["source_content_sha256"] = fact["source_content_sha256"]
        _write_json(autonomy_root(operator_root) / "trusted_knowledge_acquisition_route_latest.json", route)
    _append_ledger(operator_root, "directive_support_source_plans", source_plan)
    _write_json(
        autonomy_root(operator_root) / "directive_support_source_plan_latest.json",
        source_plan,
    )
    worker = {
        "schema_name": "TrustedKnowledgeRetrievalWorker",
        "schema_version": AUTONOMY_SCHEMA_VERSION,
        "created_at": _now(),
        "trusted_knowledge_retrieval_worker_id": "",
        "support_request_id": str(worker_context.get("support_request_id", "") or ""),
        "current_provider_support_request_id": str(worker_context.get("support_request_id", "") or ""),
        "provider_field_lane_request_id": str(
            provider_field_lane_request.get("provider_field_lane_request_id", "") or ""
        ),
        "directive_id": str(worker_context.get("directive_id", "") or ""),
        "target_artifact": str(
            provider_field_lane_request.get("target_artifact", "")
            or worker_context.get("target_artifact", "")
            or ""
        ),
        "cheap_source_retrieval_state": str(route.get("cheap_source_retrieval_state", "") or ""),
        "cheap_source_candidate_count": int(route.get("cheap_source_candidate_count", 0) or 0),
        "cheap_source_rows_extracted_count": int(route.get("cheap_source_rows_extracted_count", 0) or 0),
        "operator_seed_pack_policy": str(route.get("operator_seed_pack_policy", "") or ""),
        "openai_escalation_avoided": bool(int(source_plan.get("source_candidate_count", 0) or 0)),
        "openai_escalation_required": bool(route.get("openai_escalation_required", False)),
        "accepted_requested_row_ids": list(route.get("accepted_requested_row_ids", []) or []),
        "uncovered_after_cheap_sources": list(route.get("uncovered_after_cheap_sources", []) or []),
        "retrieved_knowledge_refs": list(route.get("retrieved_knowledge_refs", []) or [])[:40],
        "source_plan": source_plan,
        "extracted_source_rows": extracted["rows"],
        "source_cache_rejections": extracted["rejected"],
        "source_field_validation_reason": validation_reason,
        "validated_source_fields": validated,
        "grants_execution_authority": False,
    }
    worker["trusted_knowledge_retrieval_worker_id"] = _record_id(
        "trusted-knowledge-retrieval-worker",
        {
            "support_request_id": worker["support_request_id"],
            "provider_field_lane_request_id": worker["provider_field_lane_request_id"],
            "cheap_source_candidate_count": worker["cheap_source_candidate_count"],
            "uncovered_after_cheap_sources": worker["uncovered_after_cheap_sources"],
        },
    )
    record = _append_ledger(operator_root, "trusted_knowledge_retrieval_workers", worker)
    _write_json(
        autonomy_root(operator_root) / "trusted_knowledge_retrieval_worker_latest.json",
        record,
    )
    return record


def _merge_knowledge_route_fields(target: dict[str, Any], route: Mapping[str, Any]) -> None:
    for key in (
        "trusted_knowledge_acquisition_route_id",
        "knowledge_acquisition_route",
        "cheap_source_attempts",
        "cheap_source_attempt_count",
        "cheap_source_retrieval_state",
        "cheap_source_candidate_count",
        "cheap_source_rows_extracted_count",
        "operator_seed_pack_policy",
        "openai_escalation_avoided",
        "openai_escalation_required",
        "openai_escalation_reason",
        "retrieved_knowledge_refs",
        "uncovered_after_cheap_sources",
        "evidence_questions",
    ):
        target[key] = route.get(key, [] if key.endswith("s") else "")
    target["grants_execution_authority"] = False


def _knowledge_acquisition_pattern_key(route: Mapping[str, Any]) -> str:
    basis = {
        "target_artifact": str(route.get("target_artifact", "") or ""),
        "route": list(route.get("knowledge_acquisition_route", []) or [])[:3],
        "source_kinds": [
            str(attempt.get("source_kind", "") or "")
            for attempt in list(route.get("cheap_source_attempts", []) or [])
            if isinstance(attempt, Mapping)
            and str(attempt.get("attempt_state", "") or "") in {"accepted", "partial", "candidate_normalized"}
        ],
    }
    return "knowledge-acquisition-pattern-" + _hash_payload(basis, length=12)


def _record_knowledge_acquisition_pattern_evidence(
    operator_root: str | Path,
    *,
    route: Mapping[str, Any],
) -> dict[str, Any]:
    if not bool(route.get("openai_escalation_avoided", False)) and not list(
        route.get("retrieved_knowledge_refs", []) or []
    ):
        return {}
    pattern_key = _knowledge_acquisition_pattern_key(route)
    route_signature = list(route.get("knowledge_acquisition_route", []) or [])
    source_signature = [
        str(attempt.get("source_kind", "") or "")
        for attempt in list(route.get("cheap_source_attempts", []) or [])
        if isinstance(attempt, Mapping)
        and str(attempt.get("attempt_state", "") or "") in {"accepted", "partial", "candidate_normalized"}
    ]
    prior_count = 0
    for record in _read_ledger(operator_root, "knowledge_acquisition_pattern_evidence", limit=20):
        if str(record.get("target_artifact", "") or "") != str(route.get("target_artifact", "") or ""):
            continue
        if list(record.get("knowledge_acquisition_route", []) or [])[:3] != route_signature[:3]:
            continue
        record_source_signature = [
            str(ref.get("source_kind", "") or "")
            for ref in list(record.get("retrieved_knowledge_refs", []) or [])
            if isinstance(ref, Mapping) and str(ref.get("source_kind", "") or "")
        ]
        if source_signature and not any(source in set(record_source_signature) for source in source_signature):
            continue
        prior_count += 1
    skill_candidate: dict[str, Any] = {}
    if prior_count >= 1 and bool(route.get("openai_escalation_avoided", False)):
        skill_candidate = {
            "schema_name": "TrustedKnowledgeSkillCandidate",
            "schema_version": AUTONOMY_SCHEMA_VERSION,
            "skill_candidate_id": "source_query_pattern_for_"
            + re.sub(r"[^a-z0-9]+", "_", str(route.get("target_artifact", "") or "support_lane").lower()).strip("_")
            + "_v1",
            "skill_candidate_state": "review_only_candidate",
            "pattern_key": pattern_key,
            "consumption_required_before_trust": True,
            "strict_usefulness_gate_passed": False,
            "grants_execution_authority": False,
        }
    evidence = {
        "schema_name": "KnowledgeAcquisitionPatternEvidence",
        "schema_version": AUTONOMY_SCHEMA_VERSION,
        "created_at": _now(),
        "knowledge_acquisition_pattern_evidence_id": "",
        "knowledge_acquisition_pattern_key": pattern_key,
        "support_request_id": str(route.get("support_request_id", "") or ""),
        "target_artifact": str(route.get("target_artifact", "") or ""),
        "knowledge_acquisition_route": list(route.get("knowledge_acquisition_route", []) or []),
        "cheap_source_attempt_count": int(route.get("cheap_source_attempt_count", 0) or 0),
        "openai_escalation_avoided": bool(route.get("openai_escalation_avoided", False)),
        "retrieved_knowledge_refs": list(route.get("retrieved_knowledge_refs", []) or [])[:20],
        "accepted_requested_row_ids": list(route.get("accepted_requested_row_ids", []) or []),
        "trusted_knowledge_skill_candidate": skill_candidate,
        "strict_usefulness_gate_passed": False,
        "grants_execution_authority": False,
    }
    evidence["knowledge_acquisition_pattern_evidence_id"] = _record_id(
        "knowledge-pattern",
        evidence,
    )
    record = _append_ledger(operator_root, "knowledge_acquisition_pattern_evidence", evidence)
    _write_json(autonomy_root(operator_root) / "knowledge_acquisition_pattern_evidence_latest.json", record)
    return record


def _directive_build_grade_support_digest(
    operator_root: str | Path,
    context: Mapping[str, Any],
) -> dict[str, Any]:
    readiness = _trusted_source_readiness(operator_root)
    raw_request = context.get("provider_field_lane_request", {})
    provider_field_lane_request = _provider_field_lane_request_from_current_context(context)
    operator_seed_pack_policy = _operator_seed_pack_policy(context)
    digest: dict[str, Any] = {
        "schema_name": "DirectiveBuildGradeSupportDigest",
        "schema_version": AUTONOMY_SCHEMA_VERSION,
        "created_at": _now(),
        "directive_build_grade_support_digest_id": "",
        "support_request_id": str(context.get("support_request_id", "") or ""),
        "directive_id": str(context.get("directive_id", "") or ""),
        "target_artifact": str(context.get("target_artifact", "") or ""),
        "requested_pack_family": str(context.get("requested_pack_family", "") or ""),
        "requested_tags": list(context.get("requested_tags", []) or [])[:16],
        "status": "blocked",
        "provider_id": TRUSTED_SOURCE_EXTERNAL_PROVIDER_ID,
        "provider_ready": bool(readiness.get("ready", False)),
        "provider_model": str(readiness.get("selected_model", "")),
        "provider_blocker": str(readiness.get("blocker", "")),
        "child_support_rows": [],
        "child_support_row_count": 0,
        "relevance_tags": [],
        "rejected_claims": [],
        "weak_claims": [],
        "trusted_source_attempts": [],
        "trusted_source_attempt_count": 0,
        "trusted_source_response_status": "",
        "trusted_source_failure_class": "",
        "trusted_source_parse_outcome": "unattempted",
        "trusted_source_repaired_output": False,
        "trusted_source_rejection_reason": "",
        "digest_source": "external_provider_build_grade_support",
        "provider_field_lane_request_id": str(
            context.get("provider_field_lane_request_id", "")
            or context.get("support_request_id", "")
            or provider_field_lane_request.get("provider_field_lane_request_id", "")
            or ""
        ),
        "provider_field_lane_request": provider_field_lane_request,
        "accepted_field_lane_rows": [],
        "rejected_field_lane_rows": [],
        "requested_rows": list(provider_field_lane_request.get("requested_rows", []) or []),
        "requested_row_count": int(provider_field_lane_request.get("requested_row_count", 0) or 0),
        "accepted_requested_row_ids": [],
        "uncovered_requested_row_ids": list(
            provider_field_lane_request.get("uncovered_requested_row_ids", []) or []
        ),
        "rejected_requested_rows": [],
        "abstract_lane_decomposition_state": str(
            provider_field_lane_request.get("abstract_lane_decomposition_state", "") or ""
        ),
        "abstract_lane_decomposition_reason": str(
            provider_field_lane_request.get("abstract_lane_decomposition_reason", "") or ""
        ),
        "abstract_source_requested_row_ids": list(
            provider_field_lane_request.get("abstract_source_requested_row_ids", []) or []
        ),
        "decomposed_requested_row_ids": list(
            provider_field_lane_request.get("decomposed_requested_row_ids", []) or []
        ),
        "decomposed_abstract_requested_rows": list(
            provider_field_lane_request.get("decomposed_abstract_requested_rows", []) or []
        ),
        "source_acquisition_from_design_row_ids": list(
            provider_field_lane_request.get("source_acquisition_from_design_row_ids", []) or []
        ),
        "operator_seed_pack_policy": operator_seed_pack_policy,
        "knowledge_acquisition_route": [],
        "cheap_source_attempts": [],
        "cheap_source_attempt_count": 0,
        "openai_escalation_avoided": False,
        "openai_escalation_required": False,
        "openai_escalation_reason": "",
        "retrieved_knowledge_refs": [],
        "uncovered_after_cheap_sources": [],
        "evidence_questions": _requested_row_evidence_questions(context, provider_field_lane_request),
        "trusted_knowledge_skill_candidate": {},
        "field_lane_uncovered_fields": list(provider_field_lane_request.get("required_fields", []) or []),
        "field_lane_uncovered_roles": list(provider_field_lane_request.get("required_roles", []) or []),
        "support_evidence_contract_passed": False,
        "redaction_status": "redacted",
        "protected_root_write_allowed": False,
        "charter_mutated": False,
        "grants_execution_authority": False,
        **_trusted_source_workflow_profile_metadata(),
    }
    selected_model = str(readiness.get("selected_model", "") or TRUSTED_SOURCE_EXTERNAL_MODEL_PREFERENCE[0])
    partial_seed_validated: dict[str, Any] = {}
    partial_seed_id = ""
    prior_accepted_requested_row_ids = [
        str(item or "").strip()
        for item in list(
            provider_field_lane_request.get("accepted_requested_row_ids", [])
            or context.get("accepted_requested_row_ids", [])
            or []
        )
        if str(item or "").strip()
    ]
    current_requested_row_ids: list[str] = []
    for row in list(provider_field_lane_request.get("requested_rows", []) or []):
        if not isinstance(row, Mapping):
            continue
        requested_id = str(row.get("requested_row_id", "") or "").strip()
        if requested_id:
            current_requested_row_ids.append(requested_id)
    for requested_id in list(provider_field_lane_request.get("uncovered_requested_row_ids", []) or []):
        requested_id = str(requested_id or "").strip()
        if requested_id:
            current_requested_row_ids.append(requested_id)
    historical_accepted_requested_row_ids = _historical_accepted_requested_row_ids_for_support(
        operator_root,
        support_request_id=str(context.get("support_request_id", "") or ""),
        target_artifact=str(context.get("target_artifact", "") or ""),
        current_requested_row_ids=current_requested_row_ids,
    )
    if historical_accepted_requested_row_ids:
        prior_accepted_requested_row_ids = list(
            dict.fromkeys(prior_accepted_requested_row_ids + historical_accepted_requested_row_ids)
        )
        provider_field_lane_request = dict(provider_field_lane_request)
        provider_field_lane_request["accepted_requested_row_ids"] = prior_accepted_requested_row_ids
        historical_set = set(prior_accepted_requested_row_ids)
        remaining_uncovered_requested_row_ids = [
            str(item or "").strip()
            for item in list(provider_field_lane_request.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip() and str(item or "").strip() not in historical_set
        ]
        if remaining_uncovered_requested_row_ids:
            provider_field_lane_request = _provider_field_lane_request_subset(
                provider_field_lane_request,
                remaining_uncovered_requested_row_ids,
            )
        provider_field_lane_request["accepted_requested_row_ids"] = prior_accepted_requested_row_ids
        provider_field_lane_request["uncovered_requested_row_ids"] = remaining_uncovered_requested_row_ids
        provider_field_lane_request[
            "historical_accepted_requested_row_ids_recovered"
        ] = historical_accepted_requested_row_ids
        digest["provider_field_lane_request"] = provider_field_lane_request
        digest["requested_rows"] = list(provider_field_lane_request.get("requested_rows", []) or [])
        digest["requested_row_count"] = int(
            provider_field_lane_request.get("requested_row_count", 0) or 0
        )
        digest["evidence_questions"] = _requested_row_evidence_questions(
            context,
            provider_field_lane_request,
        )
        digest["accepted_requested_row_ids"] = prior_accepted_requested_row_ids
        digest["uncovered_requested_row_ids"] = list(
            provider_field_lane_request.get("uncovered_requested_row_ids", []) or []
        )
        digest["historical_accepted_requested_row_ids_recovered"] = (
            historical_accepted_requested_row_ids
        )
        digest["provider_latest_freshness_state"] = (
            "current_support_request_with_historical_accepted_rows_recovered"
        )
    (
        closed_accepted_requested_row_ids,
        closed_uncovered_requested_row_ids,
        abstract_parent_closed_requested_row_ids,
    ) = _close_decomposed_abstract_requested_rows(
        accepted_requested_row_ids=prior_accepted_requested_row_ids,
        uncovered_requested_row_ids=provider_field_lane_request.get("uncovered_requested_row_ids", [])
        or [],
        decomposed_abstract_requested_rows=provider_field_lane_request.get(
            "decomposed_abstract_requested_rows", []
        )
        or [],
    )
    if abstract_parent_closed_requested_row_ids:
        prior_accepted_requested_row_ids = closed_accepted_requested_row_ids
        provider_field_lane_request = dict(provider_field_lane_request)
        provider_field_lane_request["accepted_requested_row_ids"] = closed_accepted_requested_row_ids
        provider_field_lane_request["uncovered_requested_row_ids"] = closed_uncovered_requested_row_ids
        provider_field_lane_request["abstract_parent_closure_state"] = (
            "closed_from_decomposed_requested_rows"
        )
        provider_field_lane_request["abstract_parent_closed_requested_row_ids"] = (
            abstract_parent_closed_requested_row_ids
        )
        digest["provider_field_lane_request"] = provider_field_lane_request
        digest["accepted_requested_row_ids"] = closed_accepted_requested_row_ids
        digest["uncovered_requested_row_ids"] = closed_uncovered_requested_row_ids
        digest["abstract_parent_closure_state"] = "closed_from_decomposed_requested_rows"
        digest["abstract_parent_closed_requested_row_ids"] = abstract_parent_closed_requested_row_ids
        digest["provider_latest_freshness_state"] = (
            "current_support_request_with_decomposed_abstract_parent_closed"
        )
    if abstract_parent_closed_requested_row_ids and not closed_uncovered_requested_row_ids:
        evidence_requested_ids = [
            requested_id
            for requested_id in closed_accepted_requested_row_ids
            if requested_id not in set(abstract_parent_closed_requested_row_ids)
        ]
        recovered_rows = _historical_engineering_evidence_rows_for_requested_ids(
            operator_root,
            support_request_id=str(context.get("support_request_id", "") or ""),
            target_artifact=str(context.get("target_artifact", "") or ""),
            requested_row_ids=evidence_requested_ids,
        )
        if recovered_rows:
            digest["status"] = "completed"
            digest["digest_source"] = "historical_engineering_evidence_recovered_for_decomposed_abstract_lane"
            digest["child_support_rows"] = recovered_rows
            digest["child_support_row_count"] = len(recovered_rows)
            digest["accepted_field_lane_rows"] = recovered_rows
            digest["accepted_child_support_row_count"] = len(recovered_rows)
            digest["rejected_child_support_row_count"] = 0
            digest["provider_blocker"] = ""
            digest["trusted_source_failure_class"] = ""
            digest["trusted_source_rejection_reason"] = ""
            digest["trusted_source_attempts"] = []
            digest["trusted_source_attempt_count"] = 0
            digest["source_candidate_count"] = len(recovered_rows)
            digest["source_query_requested_row_ids"] = []
            digest["generated_search_queries"] = []
            digest["source_plan"] = {
                "schema_name": "DirectiveSupportSourcePlan",
                "status": "completed",
                "target_artifact": str(context.get("target_artifact", "") or ""),
                "source_candidate_count": len(recovered_rows),
                "source_candidates": [],
                "source_query_generation_state": "not_required",
                "source_query_generation_reason": "decomposed_abstract_lanes_already_accepted",
                "generated_search_queries": [],
                "search_queries": [],
                "source_query_requested_row_ids": [],
                "grants_execution_authority": False,
            }
            quality = _provider_quality_assessment(
                operator_root,
                support_request_id=str(context.get("support_request_id", "") or ""),
                directive_id=str(context.get("directive_id", "") or ""),
                target_artifact=str(context.get("target_artifact", "") or ""),
                required_fields=list(context.get("missing_fields", []) or []),
                accepted_rows=recovered_rows,
                rejected_reasons=[],
            )
            digest["provider_output_quality_state"] = str(
                quality.get("provider_output_quality_state", "") or "accepted"
            )
            digest["provider_output_quality_assessment_id"] = str(
                quality.get("provider_output_quality_assessment_id", "") or ""
            )
            digest["row_acceptance_ratio"] = float(quality.get("row_acceptance_ratio", 1.0) or 1.0)
            digest["field_coverage_ratio"] = float(quality.get("field_coverage_ratio", 1.0) or 1.0)
            digest["source_grounding_state"] = str(
                quality.get("source_grounding_state", "") or "source_backed"
            )
            digest["domain_match_state"] = str(
                quality.get("domain_match_state", "") or "current_support_request"
            )
            digest["support_evidence_contract_passed"] = True
            workbench = _field_lane_support_workbench_assessment(
                operator_root,
                digest=digest,
                context=context,
            )
            digest["field_lane_support_workbench_assessment_id"] = str(
                workbench.get("field_lane_support_workbench_assessment_id", "") or ""
            )
            digest["field_lane_workbench_state"] = str(
                workbench.get("field_lane_workbench_state", "") or ""
            )
            digest["directive_build_grade_support_digest_id"] = _record_id(
                "build-grade-support",
                digest,
            )
            record = _append_ledger(operator_root, "directive_build_grade_support_digests", digest)
            _write_json(
                autonomy_root(operator_root) / "directive_build_grade_support_digest_latest.json",
                record,
            )
            return record
    seed_result = (
        {}
        if operator_seed_pack_policy == "disabled_by_operator_experiment"
        else _seed_pack_rows_for_build_grade_request(
            operator_root,
            context=context,
            provider_field_lane_request=provider_field_lane_request,
        )
    )
    knowledge_route = _trusted_knowledge_acquisition_route(
        operator_root,
        context=context,
        provider_field_lane_request=provider_field_lane_request,
        seed_result=seed_result,
    )
    knowledge_route = _append_ledger(
        operator_root,
        "trusted_knowledge_acquisition_routes",
        knowledge_route,
    )
    _write_json(autonomy_root(operator_root) / "trusted_knowledge_acquisition_route_latest.json", knowledge_route)
    _merge_knowledge_route_fields(digest, knowledge_route)
    if seed_result and bool(seed_result.get("seed_pack_partial_acquisition", False)):
        partial_seed_validated = dict(seed_result.get("validated", {}) or {})
        partial_seed_id = str(seed_result.get("operator_seed_pack_id", "") or "")
        partial_uncovered_ids = [
            str(item or "").strip()
            for item in list(partial_seed_validated.get("uncovered_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        partial_accepted_ids = [
            str(item or "").strip()
            for item in list(partial_seed_validated.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        if partial_uncovered_ids:
            provider_field_lane_request = _provider_field_lane_request_subset(
                provider_field_lane_request,
                partial_uncovered_ids,
            )
            provider_field_lane_request["accepted_requested_row_ids"] = list(
                dict.fromkeys(prior_accepted_requested_row_ids + partial_accepted_ids)
            )
            provider_field_lane_request["uncovered_requested_row_ids"] = partial_uncovered_ids
            digest["provider_field_lane_request"] = provider_field_lane_request
            digest["requested_rows"] = list(provider_field_lane_request.get("requested_rows", []) or [])
            digest["requested_row_count"] = int(
                provider_field_lane_request.get("requested_row_count", 0) or 0
            )
            digest["uncovered_requested_row_ids"] = partial_uncovered_ids
            digest["accepted_requested_row_ids"] = partial_accepted_ids
            knowledge_route = _trusted_knowledge_acquisition_route(
                operator_root,
                context=context,
                provider_field_lane_request=provider_field_lane_request,
                seed_result=seed_result,
            )
            knowledge_route = _append_ledger(
                operator_root,
                "trusted_knowledge_acquisition_routes",
                knowledge_route,
            )
            _write_json(
                autonomy_root(operator_root) / "trusted_knowledge_acquisition_route_latest.json",
                knowledge_route,
            )
            _merge_knowledge_route_fields(digest, knowledge_route)
    elif seed_result:
        seed_validated = dict(seed_result.get("validated", {}) or {})
        seed_rows = list(seed_validated.get("child_support_rows", []) or [])
        if prior_accepted_requested_row_ids:
            recovered_seed_context_rows = _historical_engineering_evidence_rows_for_requested_ids(
                operator_root,
                support_request_id=str(context.get("support_request_id", "") or ""),
                target_artifact=str(context.get("target_artifact", "") or ""),
                requested_row_ids=prior_accepted_requested_row_ids,
            )
            rows_by_requested_id: dict[str, dict[str, Any]] = {}
            for row in list(recovered_seed_context_rows) + seed_rows:
                if not isinstance(row, Mapping):
                    continue
                requested_id = str(row.get("requested_row_id", "") or "").strip()
                if requested_id and requested_id not in rows_by_requested_id:
                    rows_by_requested_id[requested_id] = dict(row)
            if rows_by_requested_id:
                seed_rows = list(rows_by_requested_id.values())
        seed_id = str(seed_result.get("operator_seed_pack_id", "") or "")
        source_plan = _seed_source_plan_from_rows(
            context=context,
            provider_field_lane_request=provider_field_lane_request,
            seed_pack_id=seed_id,
            rows=seed_rows,
        )
        _append_ledger(operator_root, "directive_support_source_plans", source_plan)
        _write_json(autonomy_root(operator_root) / "directive_support_source_plan_latest.json", source_plan)
        digest["source_plan"] = {
            "schema_name": str(source_plan.get("schema_name", "") or ""),
            "source_plan_id": str(source_plan.get("source_plan_id", "") or ""),
            "status": str(source_plan.get("status", "") or ""),
            "target_artifact": str(source_plan.get("target_artifact", "") or ""),
            "source_candidate_count": int(source_plan.get("source_candidate_count", 0) or 0),
            "source_candidates": list(source_plan.get("source_candidates", []) or [])[:10],
            "source_query_generation_state": str(
                source_plan.get("source_query_generation_state", "") or ""
            ),
            "source_query_generation_reason": str(
                source_plan.get("source_query_generation_reason", "") or ""
            ),
            "generated_search_queries": list(source_plan.get("generated_search_queries", []) or []),
            "search_queries": list(source_plan.get("search_queries", []) or []),
            "source_query_requested_row_ids": list(
                source_plan.get("source_query_requested_row_ids", []) or []
            ),
            "abstract_lane_decomposition_state": str(
                source_plan.get("abstract_lane_decomposition_state", "")
                or provider_field_lane_request.get("abstract_lane_decomposition_state", "")
                or ""
            ),
            "abstract_lane_decomposition_reason": str(
                source_plan.get("abstract_lane_decomposition_reason", "")
                or provider_field_lane_request.get("abstract_lane_decomposition_reason", "")
                or ""
            ),
            "abstract_source_requested_row_ids": list(
                source_plan.get("abstract_source_requested_row_ids", [])
                or provider_field_lane_request.get("abstract_source_requested_row_ids", [])
                or []
            ),
            "decomposed_requested_row_ids": list(
                source_plan.get("decomposed_requested_row_ids", [])
                or provider_field_lane_request.get("decomposed_requested_row_ids", [])
                or []
            ),
            "grants_execution_authority": False,
            **_trusted_source_workflow_profile_metadata(source_plan),
        }
        digest["source_plan_id"] = str(source_plan.get("source_plan_id", "") or "")
        digest["source_candidate_count"] = int(source_plan.get("source_candidate_count", 0) or 0)
        digest["status"] = "completed"
        digest["digest_source"] = "operator_seed_pack_build_grade_support"
        digest["operator_seed_pack_used"] = True
        digest["operator_seed_pack_id"] = seed_id
        digest["trusted_source_attempts"] = []
        digest["trusted_source_attempt_count"] = 0
        digest["trusted_source_repaired_output"] = False
        digest["provider_blocker"] = ""
        digest["trusted_source_failure_class"] = ""
        digest["trusted_source_rejection_reason"] = ""
        digest.update(seed_validated)
        digest["child_support_rows"] = seed_rows
        digest["child_support_row_count"] = len(seed_rows)
        seed_accepted_ids = [
            str(item or "").strip()
            for item in list(seed_validated.get("accepted_requested_row_ids", []) or [])
            if str(item or "").strip()
        ]
        merged_seed_accepted_ids = list(
            dict.fromkeys(prior_accepted_requested_row_ids + seed_accepted_ids)
        )
        digest["accepted_requested_row_ids"] = merged_seed_accepted_ids
